  ui_story_5012_50120101_14_dialog_content = "Tuve un <color=#FFB400>sueño</color>.",
  ui_story_5012_50120101_15_dialog_content = "¿Una pesadilla?",
  ui_story_5012_50120101_16_dialog_content = "Yo no lo llamaría así, pero todavía estoy tratando de ordenarlo en mi mente.",
  ui_story_5012_50120101_17_dialog_content = "¿Es así? Es raro. ¿Te importa contarme el sueño?",
  ui_story_5012_50120101_18_dialog_content = "Comenzó con el sonido de campanillas de viento.",
  ui_story_5012_50120101_19_dialog_content = "Soñé que estaba bloqueado en una jaula de pájaros, y que había cristales rotos por todas partes en el suelo.",
  ui_story_5012_50120101_20_dialog_content = "Miré de cerca y vi imágenes del futuro lejano en cada fragmento.",
