  ui_story_5012_50120101_33_dialog_content = "Ni siquiera has bebido el té todavía.",
  ui_story_5012_50120101_34_dialog_content = "... Mmm, me gusta su fresca fragancia. No recuerdo haber tenido este tipo de té antes en el Palacio de Invierno.",
  ui_story_5012_50120101_35_dialog_content = "Es una mezcla especial de té de flores únicamente para el <color=#FFB400>nuevo año</color>. Me alegro de que te guste.",
  ui_story_5012_50120101_36_dialog_content = "Gracias, señor.",
  ui_story_5012_50120101_37_dialog_content = "Por favor, Su Majestad, llámeme Novio. Que hará.",
  ui_story_5012_50120101_38_dialog_content = "Es mi deber y honor estar a su lado.",
  ui_story_5012_50120101_39_dialog_content = "¿Cómo va la preparación para el nuevo año?",
