  ui_story_5012_50120101_55_dialog_content = "Eres madrugador, y muy trabajador, Tweety.",
  ui_story_5012_50120101_56_dialog_content = "Deja la carta en la puerta.",
  ui_story_5012_50120101_57_dialog_content = "¡No, no puedo! Es una carta muy especial. ¡Debes leerla ahora!",
