  ui_story_5012_50120101_59_dialog_content = "¿Eh? ¿Una carta de la Reina?",
  ui_story_5012_50120101_60_dialog_content = "Deja de perder ed tiempo. ¡Tengo otras cartas que entregar!",
  ui_story_5012_50120101_61_dialog_content = "Okey, okey, ya voy.",
  ui_story_5012_50120101_62_dialog_content = "Déjame ver... ¿Una invitación?",
