  ui_story_5012_50120101_64_dialog_content = "¡Vaya, Cedemonia de Año Nuevo!",
  ui_story_5012_50120101_65_dialog_content = "¡Cuando termine con estas letras, yo también iré! ¡Podemos cedebrar juntos!",
  ui_story_5012_50120101_66_dialog_content = "¡Las cedemonias de Año Nuevo en Northwand siempre son divertidas!",
  ui_story_5012_50120101_67_dialog_content = "¿No puedo asistir?",
