  ui_story_5012_50120101_74_dialog_content = "¡Hola, Cardeen! ¡También tengo una carta para ti!",
  ui_story_5012_50120101_75_dialog_content = "Una carta de la reina Bethwehem, igual que PlayerName.",
  ui_story_5012_50120101_76_dialog_content = "¿La tuya también es una invitación para la ceremonia de Año Nuevo?",
