  ui_story_5012_50120101_91_dialog_content = "Oye, dice que puedes llevarte a un familiar contigo...",
  ui_story_5012_50120101_92_dialog_content = "¿Miembro de la familia? ¡Pero ni siquiera estoy seguro de que iría!",
  ui_story_5012_50120101_93_dialog_content = "Ejem. ¿Quién está hablando de ti, PlayerName?",
  ui_story_5012_50120101_94_dialog_content = "No te importaría traerme a mí, tu antiguo compañero de clase, como miembro de la familia, ¿verdad? Carleen?",
  ui_story_5012_50120101_95_dialog_content = "No me importa, pero tienes que prometerme...",
  ui_story_5012_50120101_96_dialog_content = "¡No te preocupes, no seré una vergüenza!",
  ui_story_5012_50120101_97_dialog_content = "¿Y has olvidado que acabo de conocer a Su Majestad? Bethlehem en Lumópolis?",
  ui_story_5012_50120101_98_dialog_content = "Empaca tus maletas, entonces. Tú también, PlayerName.",
  ui_story_5012_50120101_99_dialog_content = "Es un largo camino hasta Northland. Tenemos que partir lo antes posible.",
  ui_story_5012_50120101_100_dialog_content = "Espera, ¿no puedo opinar en esto? ¡Pensé que era una invitación, no una citación!",
