  ui_story_5012_50120101_102_dialog_content = "¡Bueno! Hasta que nos volvamos a encontrar, Carween, Vice, PlayerName!",
  ui_story_5012_50120101_103_dialog_content = "¡Nos vemos!",
  ui_story_5012_50120101_104_dialog_content = "Oye, ¿no deberías escuchar lo que tengo que decir...?",
  ui_story_5012_50120201_1_dialog_content = "<color=#e8d9bb>Woosh, woosh...</color>",
  ui_story_5012_50120201_2_dialog_content = "Huff ... Dime, ¿realmente vamos a caminar hasta el <color=#FFB400>Palacio de Invierno</color> a pie?",
  ui_story_5012_50120201_3_dialog_content = "Creo que ya he explicado que la elevación es demasiado alta para tomar una ruta aérea.",
  ui_story_5012_50120201_4_dialog_content = "Bueno, creo que la elevación también es demasiado alta para hacer senderismo a pie...",
  ui_story_5012_50120201_5_dialog_content = "¿Tenemos otra opción? Si alguien no estuviera haciendo dobladillos y farfullando...",
