  ui_story_5012_50120201_11_dialog_content = "¡¿Qué?!",
  ui_story_5012_50120201_12_dialog_content = "<size=35><color=#e8d9bb>Clac, clac, clac...</color></size>",
  ui_story_5012_50120201_13_dialog_content = "Lo estoy perdiendo. Tengo tantas ganas de dar un paseo que estoy alucinando con un carruaje.",
  ui_story_5012_50120201_14_dialog_content = "Creo que también estoy alucinando como PlayerName...",
  ui_story_5012_50120201_15_dialog_content = "No es una alucinación, pero tampoco un carruaje.",
  ui_story_5012_50120201_16_dialog_content = "<color=#e8d9bb>*clac, clac, clac*</color>",
  ui_story_5012_50120201_17_dialog_content = "¡Oh, lo veo! ¿Eso es un trineo de renos?",
  ui_story_5012_50120201_18_dialog_content = "¡Oye! ¡Detente, por favor! ¿Puedes llevarnos...?",
  ui_story_5012_50120201_19_dialog_content = "<size=45><color=#e8d9bb>Clac, clac, clac...</color></size>",
  ui_story_5012_50120201_20_dialog_content = "¡Whoa!",
  ui_story_5012_50120201_21_dialog_content = "<color=#e8d9bb>Patinazo...</color>",
  ui_story_5012_50120201_22_dialog_content = "¡Oye, no te quedes en medio de la carretera!",
  ui_story_5012_50120201_23_dialog_content = "¡Eso estuvo cerca! Si no me rompiera a tiempo...",
  ui_story_5012_50120201_24_dialog_content = "Lo siento, es culpa nuestra. ¿Estás bien?",
  ui_story_5012_50120201_25_dialog_content = "Estoy bien, pero ¿qué haces aquí?",
  ui_story_5012_50120201_26_dialog_content = "Es casi el Año Nuevo. ¡Pensé que todos estarían en casa preparándose para celebrar!",
  ui_story_5012_50120201_27_dialog_content = "¡Sí, exactamente! Estamos invitados a pasar el Año Nuevo en Northland.",
  ui_story_5012_50120201_28_dialog_content = "Pero perdimos el último carruaje, así que...",
  ui_story_5012_50120201_29_dialog_content = "Eh, a juzgar por tu atuendo, seguro que no eres de por aquí.",
  ui_story_5012_50120201_30_dialog_content = "Espera, no son bandidos ni forajidos, ¿verdad?",
  ui_story_5012_50120201_31_dialog_content = "Recuerdo cuando los habitantes de Northland confiaban. Supongo que ahora han aprendido a ser paranoicos.",
  ui_story_5012_50120201_32_dialog_content = "¿Soy yo, o simplemente se puso frío... y suenas como... Queen? Bethlehem?",
  ui_story_5012_50120201_33_dialog_content = "No quería mencionar esto, pero la Reina me enseñó una vez.",
  ui_story_5012_50120201_34_dialog_content = "Y es Su Majestad quien envió la invitación para la ceremonia de Año Nuevo en Northland.",
  ui_story_5012_50120201_35_dialog_content = "Eso es correcto. Mira, aquí están las invitaciones.",
  ui_story_5012_50120201_36_dialog_content = "¡Ustedes son los invitados extranjeros de la reina! ¿Por qué no lo dijiste antes?",
  ui_story_5012_50120201_37_dialog_content = "Cualquier invitado de la reina es un invitado de <color=#FFB400>Lola</color>.",
  ui_story_5012_50120201_38_dialog_content = "¡Súbete!",
  ui_story_5012_50120201_39_dialog_content = "¿Ah?",
  ui_story_5012_50120201_40_dialog_content = "¡Vas al mismo lugar que yo!",
  ui_story_5012_50120201_41_dialog_content = "A menos que realmente quieras caminar hasta el palacio a pie.",
  ui_story_5012_50120201_42_dialog_content = "¡Gracias! Oye, ¿cómo subiste al trineo tan rápido, PlayerName?",
  ui_story_5012_50120201_43_dialog_content = "¡Siéntanse tranquilos y nos vamos!",
  ui_story_5012_50120201_44_dialog_content = "<color=#e8d9bb>Woosh, woosh...</color>",
  ui_story_5012_50120201_45_dialog_content = "¡Achuu!",
  ui_story_5012_50120201_46_dialog_content = "¿Estás temblando, PlayerName?",
  ui_story_5012_50120201_47_dialog_content = "Estoy bien, pero me siento un poco... ¡Achoo!",
  ui_story_5012_50120201_48_dialog_content = "Frío…",
  ui_story_5012_50120201_49_dialog_content = "Nueve de cada diez principiantes en Northland no podían soportar la temperatura helada.",
  ui_story_5012_50120201_50_dialog_content = "¡Heeheehee! ¡Pero tengo algo para eso!",
  ui_story_5012_50120201_51_dialog_content = "¡Te calentarás como una llama, lo prometo!",
  ui_story_5012_50120201_52_dialog_content = "¿Qué es?",
  ui_story_5012_50120201_53_dialog_content = "Muy simple, simplemente mueva su cuerpo, como...",
  ui_story_5012_50120201_54_dialog_content = "¡Tirando del trineo con los renos!",
  ui_story_5012_50120201_55_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5012_50120201_56_dialog_content = "No te enfades. Sólo bromeo.",
  ui_story_5012_50120201_57_dialog_content = "Ese fue un ruido aterrador que hiciste.",
  ui_story_5012_50120201_58_dialog_content = "Yo no hice ese ruido...",
  ui_story_5012_50120201_59_dialog_content = "<color=#e8d9bb>¡Boom, retumbo!</color>",
  ui_story_5012_50120201_60_dialog_content = "¡Alto, reno!",
  ui_story_5012_50120201_61_dialog_content = "Los animales están asustados... ¡Cuidado!",
  ui_story_5012_50120201_62_dialog_content = "Oye, no corras hacia el bosque, o nos estrellaremos...",
  ui_story_5012_50120201_63_dialog_content = "<color=#e8d9bb>¡Golpe, bofetada, bofetada, bofetada!</color>",
  ui_story_5012_50120201_64_dialog_content = "Ay...",
  ui_story_5012_50120201_65_dialog_content = "¿Estás herido, PlayerName?",
  ui_story_5012_50120201_66_dialog_content = "Estoy bien.",
  ui_story_5012_50120201_67_dialog_content = "De hecho, me siento mucho más caliente después de la caída.",
  ui_story_5012_50120201_68_dialog_content = "Pero, ¿dónde están todos los renos?",
  ui_story_5012_50120201_69_dialog_content = "¡Oh no, el ciervo se llevó el trineo!",
  ui_story_5012_50120201_70_dialog_content = "Los regalos por los que me esforcé tanto en conseguirlos todavía están en el trineo...",
  ui_story_5012_50120201_71_dialog_content = "¿Estamos destinados a caminar hasta Northland?",
  ui_story_5012_50120201_72_dialog_content = "Pero, ¿qué fue ese ruido? ¿Fue un trueno?",
  ui_story_5012_50120201_73_dialog_content = "Sí, probablemente fue un trueno.",
  ui_story_5012_50120201_74_dialog_content = "¿Trueno en la nieve? Esta es la primera vez que escucho sobre eso.",
  ui_story_5012_50120201_75_dialog_content = "Su Majestad me dijo que los truenos y los relámpagos solían acompañar a las ventiscas más intensas.",
  ui_story_5012_50120201_76_dialog_content = "<color=#e8d9bb>¡Boooom!</color>",
  ui_story_5012_50120201_77_dialog_content = "Mira, está empezando a nevar.",
  ui_story_5012_50120201_78_dialog_content = "Me temo que nos espera una fuerte tormenta de nieve.",
  ui_story_5012_50120201_79_dialog_content = "¡Las tormentas de nieve no son una broma!",
  ui_story_5012_50120201_80_dialog_content = "Literalmente seremos muñecos de nieve si no encontramos un refugio.",
  ui_story_5012_50120201_81_dialog_content = "No deberíamos estar lejos del Valle Escarcha de Pino. Tiene un puesto de avanzada, según recuerdo.",
  ui_story_5012_50120201_82_dialog_content = "¿Conoces algún atajo para llegar allí, Lola?",
  ui_story_5012_50120201_83_dialog_content = "¡Le preguntaste a la persona adecuada! ¡Sígueme!",
  ui_story_5012_50120201_84_dialog_content = "<color=#e8d9bb>¡Woosh, woosh!</color>",
  ui_story_5012_50120201_85_dialog_content = "Argh...",
  ui_story_5012_50120201_86_dialog_content = "¿Qué paso?",
  ui_story_5012_50120201_87_dialog_content = "Nada, solo ramitas rotas.",
  ui_story_5012_50120201_88_dialog_content = "No pensé que la nieve esponjosa pudiera golpearme la cara con tanta fuerza.",
  ui_story_5012_50120201_89_dialog_content = "Y ni siquiera puedo ver a dónde voy...",
  ui_story_5012_50120201_90_dialog_content = "La tormenta de nieve acaba de empezar. Tenemos que darnos prisa.",
  ui_story_5012_50120201_91_dialog_content = "¡Achu! Estoy casi completamente entumecido por el frío, Lola...",
  ui_story_5012_50120201_92_option_content = "¿Ya llegamos?",
  ui_story_5012_50120201_93_dialog_content = "Normalmente, deberíamos verlo pronto.",
  ui_story_5012_50120201_94_dialog_content = "Probablemente sea la poca visibilidad.",
  ui_story_5012_50120201_95_dialog_content = "Mantén los ojos abiertos, todos.",
  ui_story_5012_50120201_96_option_content = "¿Estás bien?",
  ui_story_5012_50120201_97_dialog_content = "Por supuesto. Soy local. Esto no me va a asustar.",
  ui_story_5012_50120201_98_dialog_content = "No puedo entrar en pánico, o se quedará afuera para que se seque.",
  ui_story_5012_50120201_99_dialog_content = "Tos... Está bien. Entonces cuento contigo, la más tranquila Lola.",
  ui_story_5012_50120201_100_dialog_content = "¡Mira, huellas!",
  ui_story_5012_50120201_101_dialog_content = "Quizás sean de gente que va al puesto de avanzada como nosotros.",
  ui_story_5012_50120201_102_dialog_content = "¡Podemos seguir el rastro y llegar allí!",
  ui_story_5012_50120201_103_dialog_content = "Pero la forma y el número de impresiones...",
  ui_story_5012_50120201_104_dialog_content = "Se parecían mucho a los nuestros.",
  ui_story_5012_50120201_105_dialog_content = "¿Nuestras huellas? ¡Pero acabo de encontrarlos!",
  ui_story_5012_50120201_106_dialog_content = "Carleen, estas diciendo...?",
  ui_story_5012_50120201_107_dialog_content = "Hemos estado dando vueltas por el bosque.",
  ui_story_5012_50120201_108_dialog_content = "¡¿Qué?!",
  ui_story_5012_50120201_109_dialog_content = "Lo siento, no pensé que alguna vez me perdería...",
  ui_story_5012_50120201_110_dialog_content = "Todo es mi culpa. Por favor perdoname.",
  ui_story_5012_50120201_111_dialog_content = "No seas duro contigo mismo, Lola. ¡Tiene que haber otra manera!",
  ui_story_5012_50120201_112_dialog_content = "En ese caso, ¿me soltarías, PlayerName?",
  ui_story_5012_50120201_113_dialog_content = "Tu mano está helada y realmente me duele.",
  ui_story_5012_50120201_114_dialog_content = "¿Por qué le hiciste eso a Lola, PlayerName?",
  ui_story_5012_50120201_115_dialog_content = "No fui yo. No la toqué en absoluto...",
  ui_story_5012_50120201_116_dialog_content = "¡Grrr!",
  ui_story_5012_50120201_117_dialog_content = "¡¿Eclipsites de nuevo?! ¿Ni siquiera te tomarás los días libres por la nieve?",
  ui_story_5012_50120201_118_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_5012_50120202_1_dialog_content = "¿No está Northland libre de eclipsites?",
  ui_story_5012_50120202_2_dialog_content = "Tienes que llegar a Escarcha de Pino para estar en Northland.",
  ui_story_5012_50120202_3_dialog_content = "¡Gaah!",
  ui_story_5012_50120202_4_dialog_content = "¡Torrente rápido!",
  ui_story_5012_50120202_5_dialog_content = "*Rugido*",
  ui_story_5012_50120202_6_dialog_content = "¡No intentes correr! ¡Despierta, poder de la magia!",
  ui_story_5012_50120202_7_dialog_content = "Suspiro. Cuando finalmente pueda tomar una siesta en mi cálida y suave cama...",
  ui_story_5012_50120202_8_dialog_content = "¡Grrr!",
  ui_story_5012_50120202_9_dialog_content = "Ten cuidado detrás de ti, Lola!",
  ui_story_5012_50120202_10_dialog_content = "¡Flor de hielo!",
  ui_story_5012_50120202_11_dialog_content = "¡Gracias!",
  ui_story_5012_50120202_12_dialog_content = "Ahora no es el momento. Es tabú perder el enfoque en la batalla.",
  ui_story_5012_50120202_13_dialog_content = "*Rugido*",
  ui_story_5012_50120202_14_dialog_content = "¿Soy yo o hay más eclipsites?",
  ui_story_5012_50120202_15_dialog_content = "¿Cuál es la situación, PlayerName?",
  ui_story_5012_50120202_16_dialog_content = "Siento que muchos eclipsites pululan de esta manera.",
  ui_story_5012_50120202_17_dialog_content = "¡Grrr!",
  ui_story_5012_50120202_18_dialog_content = "¡Dispersión, pétalos de hielo!",
  ui_story_5012_50120202_19_dialog_content = "No podemos seguir así por mucho tiempo. Necesitamos una solución.",
  ui_story_5012_50120202_20_dialog_content = "¿Por qué estás agachado, PlayerName? ¿Estás golpeado?",
  ui_story_5012_50120202_21_dialog_content = "Estoy viendo bailar a los <color=#FFB400>conejos</color> en el suelo.",
  ui_story_5012_50120202_22_dialog_content = "¡Este no es el momento para eso!",
  ui_story_5012_50120202_23_dialog_content = "Pero creo que están tratando de decirnos algo con la forma en que se mueven...",
  ui_story_5012_50120202_24_dialog_content = "¿Conejos, aquí? Podría ser... <color=#FFB400>Novio</color>?",
  ui_story_5012_50120202_25_dialog_content = "Oye, se están escapando...",
  ui_story_5012_50120202_26_dialog_content = "Quizás... ¡Rápido, sigue a los conejos!",
  ui_story_5012_50120202_27_dialog_content = "¡Grrr!",
  ui_story_5012_50120202_28_dialog_content = "¡Torrente rápido!",
  ui_story_5012_50120202_29_dialog_content = "Estos conejos corren como un pollo con la cabeza cortada... ¿Estás seguro de que esto es lo correcto?",
  ui_story_5012_50120202_30_dialog_content = "Es nuestra única opción. Esperemos que realmente sea él.",
  ui_story_5012_50120202_31_dialog_content = "¡Cuidado por detrás!",
  ui_story_5012_50120202_32_dialog_content = "*Rugido*",
  ui_story_5012_50120202_33_dialog_content = "Flor de Hielo—",
  ui_story_5012_50120202_X33_dialog_content = "Urgh...",
  ui_story_5012_50120202_34_dialog_content = "¡Carleen!",
  ui_story_5012_50120202_35_dialog_content = "Tos... estoy bien, Vice. Mantener PlayerName seguro, yo cubriré la retaguardia!",
  ui_story_5012_50120202_36_dialog_content = "El camino ... ¡Buenas noticias, pronto llegaremos a Escarcha de Pino!",
  ui_story_5012_50120202_37_dialog_content = "¡Grrr!",
  ui_story_5012_50120202_38_dialog_content = "¡Flor de hielo!",
  ui_story_5012_50120202_39_dialog_content = "<color=#e8d9bb>Boom! Blam!</color>",
  ui_story_5012_50120202_40_dialog_content = "Gaah...",
  ui_story_5012_50120202_41_dialog_content = "¡Achoo! ¿Qué pasa con el frente frío? ¡Oye, todos los eclipsites han sido derrotados!",
  ui_story_5012_50120202_42_dialog_content = "Así que has estado ahorrando energía todo el tiempo, Carleen?",
  ui_story_5012_50120202_43_dialog_content = "No, yo no lo hice...",
  ui_story_5012_50120202_X43_dialog_content = "Esto es-!",
  ui_story_5012_50120202_44_dialog_content = "Veo que no has estado practicando tanto, Carleen.",
  ui_story_5012_50120202_45_dialog_content = "Su Majestad?!",
  ui_story_5012_50120202_46_dialog_content = "(Nunca pensé que vería Carleen sobresaltado así...)",
  ui_story_5012_50120202_47_dialog_content = "¡Su Majestad! Novio! Waaah... Pensé que nunca te volvería a ver...",
  ui_story_5012_50120202_48_dialog_content = "Y... perdí todos los regalos que tanto intenté conseguir...",
  ui_story_5012_50120202_49_dialog_content = "Oh, Lola... que llanto bebe...",
  ui_story_5012_50120202_50_dialog_content = "Esta no es la chica engreída que se fue de Northland que yo conozco.",
  ui_story_5012_50120202_51_dialog_content = "Lola, mira detrás del carruaje, ¿son esas las cosas que perdiste?",
  ui_story_5012_50120202_52_dialog_content = "¡Vaya, Su Majestad las encontró para mí! ¡Larga vida a la Reina!",
  ui_story_5012_50120202_53_dialog_content = "Mi agradecimiento por la ayuda, Su Majestad. Lo siento, no lo hice mejor... Tos...",
  ui_story_5012_50120202_54_dialog_content = "Novio, por favor trate la lesión de Carleen.",
  ui_story_5012_50120202_55_dialog_content = "En seguida.",
  ui_story_5012_50120202_56_dialog_content = "Perdóname, PlayerName.",
  ui_story_5012_50120202_57_dialog_content = "Te invité solo para que estuvieras en peligro. Eso se refleja mal en mí como anfitrión.",
  ui_story_5012_50120202_58_dialog_content = "Está, eh, bastante bien, de verdad...",
  ui_story_5012_50120202_59_dialog_content = "Es mi culpa que perdiéramos el entrenador y necesitáramos el rescate de usted.",
  ui_story_5012_50120202_60_dialog_content = "¿Quién es el que está detrás de ti...?",
  ui_story_5012_50120202_61_dialog_content = "Saludos, Su Majestad, estoy Vice. Creo que nos conocimos en Lumopolis.",
  ui_story_5012_50120202_62_dialog_content = "Si, lo recuerdo.",
  ui_story_5012_50120202_63_dialog_content = "¡Trajiste a tu familia contigo, PlayerName!",
  ui_story_5012_50120202_64_dialog_content = "¡No, por favor no asumas eso!",
  ui_story_5012_50120202_65_dialog_content = "Perdóname, no me he presentado. Soy Novio, un ciudadano de Northland.",
  ui_story_5012_50120202_66_dialog_content = "Sube al autobús y emprenderemos el viaje...",
  ui_story_5012_50120202_67_dialog_content = "de regreso al Palacio de Invierno.",
  ui_story_5012_50120301_1_dialog_content = "<color=#e8d9bb>Clac, clac, clac...</color>",
  ui_story_5012_50120301_2_dialog_content = "¡Vaya, he vuelto, Northland!",
  ui_story_5012_50120301_3_dialog_content = "¡De la forma en que no podías esperar para irte, pensé que nunca querrías volver!",
  ui_story_5012_50120301_4_dialog_content = "Bueno, ¡tienes que salir y volver a casa! ¿No es así, Su Majestad?",
  ui_story_5012_50120301_5_dialog_content = "En tu caso, yo creo que sí.",
  ui_story_5012_50120301_6_dialog_content = "No puedo esperar para morder un pastel de miel genuino... ¡Estoy salivando solo de pensarlo!",
  ui_story_5012_50120301_7_dialog_content = "El pastel de miel en todos los demás lugares no era comestible. Lamenté no haber traído más.",
  ui_story_5012_50120301_8_dialog_content = "Así que has estado viajando, Lola? ¿A dónde fuiste?",
  ui_story_5012_50120301_9_dialog_content = "He estado en... en... Zzzzz...",
  ui_story_5012_50120301_10_dialog_content = "Lo siento por eso. El niño podía dormir en cualquier lugar.",
  ui_story_5012_50120301_11_dialog_content = "Eso es realmente un rasgo admirable.",
  ui_story_5012_50120301_12_dialog_content = "¿Oh? ¿Tienes problemas para dormir, PlayerName?",
  ui_story_5012_50120301_13_option_content = "Si",
  ui_story_5012_50120301_14_dialog_content = "Es difícil para mí conciliar el sueño cuando tengo demasiadas cosas en la cabeza.",
  ui_story_5012_50120301_15_dialog_content = "Dando vueltas y vueltas un par de veces y es el amanecer.",
  ui_story_5012_50120301_16_option_content = "No",
  ui_story_5012_50120301_17_dialog_content = "Realmente no...",
  ui_story_5012_50120301_18_dialog_content = "Pero es más difícil conciliar el sueño cuando tengo demasiadas cosas en la cabeza.",
  ui_story_5012_50120301_19_dialog_content = "Parece que aún tienes problemas por resolver.",
  ui_story_5012_50120301_20_dialog_content = "...",
  ui_story_5012_50120301_21_dialog_content = "Pero eso es normal para un niño de tu edad, pensar en tus problemas.",
  ui_story_5012_50120301_22_dialog_content = "Tengo un libro aquí que puede ayudar.",
  ui_story_5012_50120301_23_dialog_content = "Siéntete libre de navegarlo.Es un...",
  ui_story_5012_50120301_24_dialog_content = "Un viaje muy largo, después de todo.",
  ui_story_5012_50120301_25_dialog_content = "¿Eh? Este libro parece familiar...",
  ui_story_5012_50120301_X25_dialog_content = "Pero, ¿por qué no tiene título?",
  ui_story_5012_50120301_26_dialog_content = "Es diferente para todos los que lo han leído.",
  ui_story_5012_50120301_27_dialog_content = "Tengo mucha curiosidad por saber qué título le darás después de leerlo.",
  ui_story_5012_50120301_28_dialog_content = "Eso es profundo... ¿Qué hay en el libro?",
  ui_story_5012_50120301_29_dialog_content = "Mantras para posiblemente resolver sus problemas, como...",
  ui_story_5012_50120301_30_dialog_content = "De donde vengo.",
  ui_story_5012_50120301_31_dialog_content = "A dónde voy.",
  ui_story_5012_50120301_32_dialog_content = "Quién soy realmente.",
  ui_story_5012_50120301_33_dialog_content = "Quién soy yo...",
  ui_story_5012_50120301_34_dialog_content = "Quién soy...",
  ui_story_5012_50120301_35_dialog_content = "Quién...",
  ui_story_5012_50120301_36_dialog_content = "...",
  ui_story_5012_50120301_37_dialog_content = "<size=45>¡¿Quién?!</size>",
  ui_story_5012_50120301_38_dialog_content = "¿Quién eres?",
  ui_story_5012_50120301_39_dialog_content = "...",
  ui_story_5012_50120301_40_dialog_content = "¡Deja de soñar despierto y agarra un arma!",
  ui_story_5012_50120301_41_dialog_content = "¿Arma?",
  ui_story_5012_50120301_42_dialog_content = "¡Los eclipsites entraron en <color=#FFB400>Eraveil</color>!",
  ui_story_5012_50120301_43_dialog_content = "Por el bien de nuestra patria...",
  ui_story_5012_50120301_44_dialog_content = "¡Coge tu arma!",
  ui_story_5012_50120401_1_dialog_content = "<size=45>¡Rarrr!</size>",
  ui_story_5012_50120401_2_dialog_content = "¡Puaj! Tos... Maldita sea, no tengo oportunidad de usar esta arma...",
  ui_story_5012_50120401_3_dialog_content = "¡Wah, wah!",
  ui_story_5012_50120401_4_dialog_content = "¡Estoy luchando contigo con todo lo que tengo!",
  ui_story_5012_50120401_5_dialog_content = "¡Por favor, te lo ruego! Estoy embarazada... te lo ruego...",
  ui_story_5012_50120401_6_dialog_content = "¡Ven a buscar algo de este viejo tonto!",
  ui_story_5012_50120401_7_dialog_content = "...",
  ui_story_5012_50120401_8_dialog_content = "¿Por qué? ¿Cómo se llegó a esto?",
  ui_story_5012_50120401_9_dialog_content = "Si tan sólo pudiera...",
  ui_story_5012_50120401_10_dialog_content = "Empuña la Luminatics que congela todo...",
  ui_story_5012_50120401_11_dialog_content = "¿Que estoy pensando? No soy un aurorian. ¿Pero que mas puedo hacer?",
  ui_story_5012_50120401_12_dialog_content = "¡ESP! ¡Todavía tengo ESP! Pero de qué sirve eso...",
  ui_story_5012_50120401_13_dialog_content = "Déjame intentarlo...",
  ui_story_5012_50120401_14_option_content = "¡Enlace mental!",
  ui_story_5012_50120401_15_dialog_content = "<anim type=Shake>&*%……@￥%...¡Rarrr!</anim>",
  ui_story_5012_50120401_16_dialog_content = "¿Qué fue eso?",
  ui_story_5012_50120401_17_dialog_content = "¿Acabo de sentir... los pensamientos de un eclipsite?",
  ui_story_5012_50120401_18_dialog_content = "¡Grrr!",
  ui_story_5012_50120401_X18_dialog_content = "¿Y solo podemos usar estas armas...?",
  ui_story_5012_50120401_19_dialog_content = "¡Canalla! ¡Escoria!",
  ui_story_5012_50120401_20_dialog_content = "¡No eres bienvenido en Eraveil! ¡Sal y no vuelvas!",
  ui_story_5012_50120401_21_dialog_content = "¡Rarrr! ¡Grrrr!",
  ui_story_5012_50120401_22_dialog_content = "¿La realidad todavía no te ha golpeado?",
  ui_story_5012_50120401_23_dialog_content = "No tienes a donde correr.",
  ui_story_5012_50120401_24_dialog_content = "¿Quién eres?",
  ui_story_5012_50120401_25_dialog_content = "¿Por qué no te preguntas eso?",
  ui_story_5012_50120401_26_dialog_content = "¡Yo sé quién soy!",
  ui_story_5012_50120401_27_dialog_content = "Bueno, entonces, ¿cuál es tu nombre?",
  ui_story_5012_50120401_28_dialog_content = "¡Es Schummer!",
  ui_story_5012_50120401_29_dialog_content = "Espera, no... \"Schummer\" es solo un nombre que recordaba.",
  ui_story_5012_50120401_30_dialog_content = "No soy Schummer, no soy Schummer... soy...",
  ui_story_5012_50120401_31_dialog_content = "<size=45>¿Quién soy?</size>",
  ui_story_5012_50120401_32_dialog_content = "Por supuesto que no eres Schummer. Schummer conocía su lugar mucho mejor que tú.",
  ui_story_5012_50120401_33_dialog_content = "Obtuvo su poder hace mucho tiempo, incluso antes que yo.",
  ui_story_5012_50120401_34_dialog_content = "Ella podía hacer lo que quisiera. ¡Oh, cómo la envidio!",
  ui_story_5012_50120401_35_dialog_content = "¡Eso no es nada de lo que estar orgulloso! ¡Vendió a los celestitas y a su propia alma!",
  ui_story_5012_50120401_36_dialog_content = "Schummer es la que no sabía quién era.",
  ui_story_5012_50120401_37_dialog_content = "¡Bravo, muy bien dicho!",
  ui_story_5012_50120401_38_dialog_content = "Si tan solo una respuesta tan justa pudiera salvar a tu pueblo...",
  ui_story_5012_50120401_39_dialog_content = "Wah, wah...",
  ui_story_5012_50120401_40_dialog_content = "¡Mi niño!",
  ui_story_5012_50120401_41_dialog_content = "¡Sálvalos, sálvalos!",
  ui_story_5012_50120401_42_dialog_content = "¿Cómo puedo salvar a todos de esta atrocidad? ¿Cómo...?",
  ui_story_5012_50120401_43_dialog_content = "Levanta la barbilla.",
  ui_story_5012_50120401_44_dialog_content = "La respuesta que buscas está justo frente a ti, suplicándote que sigas adelante.",
  ui_story_5012_50120401_45_dialog_content = "Es tan tentador que ni siquiera yo puedo soportarlo...",
  ui_story_5012_50120401_46_dialog_content = "¿Eso es una <color=#FFB400>Semilla</color>?",
  ui_story_5012_50120401_47_dialog_content = "¡Oye, sabes tus cosas!",
  ui_story_5012_50120401_48_dialog_content = "Sí, la fuente de todo el poder, la recompensa más dulce del mundo...",
  ui_story_5012_50120401_49_dialog_content = "Con él, puedes proteger a ese bebé que llora, evitar que Eraveil se queme...",
  ui_story_5012_50120401_50_dialog_content = "¡Incluso puedes crear tu civilización ideal o destruir cualquier soberanía que te parezca repugnante!",
  ui_story_5012_50120401_51_dialog_content = "¡Eso es para los eclipsites, no para mí!",
  ui_story_5012_50120401_52_dialog_content = "¡No sabes lo que es bueno para ti! ¡Todos los que te rodean morirán por tu decisión!",
  ui_story_5012_50120401_53_dialog_content = "¿No te arrepentirías?",
  ui_story_5012_50120401_54_dialog_content = "¡Consumir la Semilla sería el único arrepentimiento!",
  ui_story_5012_50120401_55_dialog_content = "¡Y no puedo dejar que los lastimes de nuevo!",
  ui_story_5012_50120401_56_option_content = "¡Enlace mental!",
  ui_story_5012_50120401_57_dialog_content = "¡Graaah!",
  ui_story_5012_50120401_58_dialog_content = "*Rugido*",
  ui_story_5012_50120401_59_dialog_content = "¡Imposible! ¿Eres responsable de esto? ¿Cómo?",
  ui_story_5012_50120401_60_dialog_content = "¡Funcionó! ¡No puedo creer que pueda manipular sus pensamientos para atacarse unos a otros!",
  ui_story_5012_50120401_61_dialog_content = "¿Puedes controlar Eclipsites? ¡Esto se está poniendo interesante!",
  ui_story_5012_50120401_62_dialog_content = "Entonces la pregunta nuevamente es, ¿qué eres realmente?",
  ui_story_5012_50120401_63_dialog_content = "Una celestita que puede controlar la eclipsita... ¿O una eclipsite en piel celestita?",
  ui_story_5012_50120401_64_dialog_content = "O quizás ninguno de los dos.",
  ui_story_5012_50120401_65_dialog_content = "<size=45>¡Cállate! ¡Cállate ahora!</size>",
  ui_story_5012_50120401_66_option_content = "¡Aumentando mi poder psíquico!",
  ui_story_5012_50120402_1_dialog_content = "Gahhh...",
  ui_story_5012_50120402_2_dialog_content = "Los Eclipsites están a punto de terminar aquí...",
  ui_story_5012_50120402_3_dialog_content = "Compañeros míos, ¡agarremos nuestras armas!",
  ui_story_5012_50120402_4_dialog_content = "¡Y dale a los monstruos su golpe final!",
  ui_story_5012_50120402_5_dialog_content = "¡Deberíamos! ¡Cargar!",
  ui_story_5012_50120402_6_dialog_content = "Gaah... Graaah...",
  ui_story_5012_50120402_7_dialog_content = "¡Y tú, traidor, no escaparás!",
  ui_story_5012_50120402_8_dialog_content = "Tos... Te arrepentirás de esto.",
  ui_story_5012_50120402_9_dialog_content = "¡Concentra tu ataque, este es el último!",
  ui_story_5012_50120402_10_dialog_content = "¡Come balas y muere!",
  ui_story_5012_50120402_11_dialog_content = "Oh... Ugh... Tos...",
  ui_story_5012_50120402_12_dialog_content = "Je, hiciste esto para proteger a los débiles detrás de ti...",
  ui_story_5012_50120402_13_dialog_content = "¿Pero sabes que elegí ser así para poder proteger a mi gente?",
  ui_story_5012_50120402_14_dialog_content = "¡Tu pueblo debe estar avergonzado de ti!",
  ui_story_5012_50120402_15_dialog_content = "Veo que todavía no entiendes. Sin mí, nadie puede proteger a mi gente.",
  ui_story_5012_50120402_16_dialog_content = "Serán aplastados.",
  ui_story_5012_50120402_17_dialog_content = "Si no lo crees, mira el eclipse que está descendiendo...",
  ui_story_5012_50120402_18_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5012_50120402_19_dialog_content = "Eraveil ha perdido.",
  ui_story_5012_50120402_20_dialog_content = "¡Esto no es real! Yo solo...",
  ui_story_5012_50120402_21_dialog_content = "¿Y qué pasa si me golpeas?",
  ui_story_5012_50120402_22_dialog_content = "Aún no puedes salvar a Eraveil, no puedes salvar a los débiles que te rodean.",
  ui_story_5012_50120402_23_dialog_content = "¿Y a dónde más puedes ir?",
  ui_story_5012_50120402_24_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  ui_story_5012_50120402_25_dialog_content = "¡Las turbas eclipsites están llegando desde otros lugares!",
  ui_story_5012_50120402_26_dialog_content = "Nos hemos quedado sin munición...",
  ui_story_5012_50120402_27_dialog_content = "¿Qué podemos hacer, a dónde podemos ir?",
  ui_story_5012_50120402_28_dialog_content = "¿Todavía no puedo salvarlos incluso cuando se me da otra oportunidad?",
  ui_story_5012_50120402_29_dialog_content = "¿Qué estoy haciendo aquí?",
  ui_story_5012_50120402_30_dialog_content = "¿Como llegué aquí?",
  ui_story_5012_50120402_31_dialog_content = "¿Hay algún lugar lejano al que tengo que ir?",
  ui_story_5012_50120402_32_dialog_content = "¿Quién soy...?",
  ui_story_5012_50120501_1_dialog_content = "¿A dónde voy...?",
  ui_story_5012_50120501_2_dialog_content = "<size=30>¿PlayerName?</size>",
  ui_story_5012_50120501_3_dialog_content = "Quién soy yo...",
  ui_story_5012_50120501_4_dialog_content = "<size=45>¡PlayerName!</size>",
  ui_story_5012_50120501_5_dialog_content = "<color=#e8d9bb>Clac, clac, clac.</color>",
  ui_story_5012_50120501_6_dialog_content = "¿Vice?",
  ui_story_5012_50120501_7_dialog_content = "Finalmente estás despierto, PlayerName.",
  ui_story_5012_50120501_8_dialog_content = "Ayúdame, rápido, Eraveil está a punto de ser...",
  ui_story_5012_50120501_9_dialog_content = "¿De qué estás hablando? Estamos en Northland.",
  ui_story_5012_50120501_10_dialog_content = "Northland?",
  ui_story_5012_50120501_11_dialog_content = "Ejem. Su Majestad te está mirando ahora mismo, PlayerName.",
  ui_story_5012_50120501_12_dialog_content = "¡Oh... Su Majestad!",
  ui_story_5012_50120501_13_dialog_content = "Debes de estar exhausto.",
  ui_story_5012_50120501_14_dialog_content = "Lamento haberme quedado dormido.",
  ui_story_5012_50120501_15_dialog_content = "Recuerdo vagamente que estaba leyendo un libro... Hmm, ¿dónde está?",
  ui_story_5012_50120501_16_dialog_content = "Ese libro ha cumplido su propósito una vez que el lector se dio cuenta de su bagaje emocional.",
  ui_story_5012_50120501_17_dialog_content = "...",
  ui_story_5012_50120501_18_dialog_content = "(Probablemente esté enojado porque solo lo hojeé...)",
  ui_story_5012_50120501_19_dialog_content = "Je, esta es la primera vez que veo a alguien que dormía más que yo.",
  ui_story_5012_50120501_20_dialog_content = "Llevas mucho tiempo dormido. ¿Algún dulce sueño?",
  ui_story_5012_50120501_21_dialog_content = "El que acabo de tener... Se sentía tan real.",
  ui_story_5012_50120501_X21_dialog_content = "Soñé... que podía controlar Eclipsites...",
  ui_story_5012_50120501_X22_dialog_content = "¿Qué? ¿Controlar Eclipsites...? Ese es un sueño loco...",
  ui_story_5012_50120501_X23_dialog_content = "Nunca escuché que los celestitas pudieran controlar los eclipsites.",
  ui_story_5012_50120501_22_dialog_content = "No es de extrañar que no pude despertarte. ¡Debes haberte perdido en la tierra de los sueños!",
  ui_story_5012_50120501_23_dialog_content = "Es una pena... Te perdiste muchos paisajes agradables en el camino debido a tu pequeño sueño.",
  ui_story_5012_50120501_24_dialog_content = "Está bien, al menos PlayerName no se perderá...",
  ui_story_5012_50120501_25_dialog_content = "El Palacio de Invierno.",
  ui_story_5012_50120501_26_dialog_content = "¿Es eso...?",
  ui_story_5012_50120501_27_dialog_content = "\"La perla brillante de Northland, el bastión reluciente bajo la aurora\".",
  ui_story_5012_50120501_28_dialog_content = "Lo leo cientos de veces, pero ver para creer.",
  ui_story_5012_50120501_29_dialog_content = "La edad no lo ha cambiado ni un ápice.",
  ui_story_5012_50120501_30_dialog_content = "Esto recuerda a mi primera visita a Northland.",
  ui_story_5012_50120501_31_dialog_content = "Y aquí pensé que Lumópolis era magnífica...",
  ui_story_5012_50120501_32_dialog_content = "Este palacio es aún más impresionante.",
  ui_story_5012_50120501_33_dialog_content = "Casi parece sacado de un cuento de hadas.",
  ui_story_5012_50120501_34_dialog_content = "Exuda calidez a pesar del entorno helado.",
  ui_story_5012_50120501_35_dialog_content = "No es de extrañar que Northland sea promocionado como un reino de libro de cuentos. Debe ser divertido vivir aquí.",
  ui_story_5012_50120501_36_dialog_content = "Ni que decir. Northland es el lugar más feliz del mundo, ¡sin excepción!",
  ui_story_5012_50120501_37_dialog_content = "Hmm, eso no sonaba como alguien que estaba tan ansioso por irse de Northland.",
  ui_story_5012_50120501_38_dialog_content = "¡He traído regalos para todos! ¡Deja de golpear a ese caballo muerto!",
  ui_story_5012_50120501_39_dialog_content = "Oh, ¿puedo bajarme de aquí, Su Majestad?",
  ui_story_5012_50120501_40_dialog_content = "¡Tengo muchas baratijas para compartir con la gente del pueblo!",
  ui_story_5012_50120501_41_dialog_content = "Seguro.",
  ui_story_5012_50120501_42_dialog_content = "¿Por qué no aprovechas esta oportunidad para mostrar PlayerName y los demás?",
  ui_story_5012_50120501_43_dialog_content = "¡Necesito tu ayuda!",
  ui_story_5012_50120501_44_dialog_content = "¡Cada hogar en estas calles recibe uno!",
  ui_story_5012_50120501_45_dialog_content = "Pensé que iba a ser una gira, pero ahora estamos reclutados para el servicio de entrega.",
  ui_story_5012_50120501_46_dialog_content = "Ejem, la gira es un cliché.",
  ui_story_5012_50120501_47_dialog_content = "¡Conocerás mucho mejor cómo vivimos de esta manera!",
  ui_story_5012_50120501_48_dialog_content = "¿Qué tal un poco de competencia, Carleen?",
  ui_story_5012_50120501_49_dialog_content = "¿Te refieres a entregar los regalos?",
  ui_story_5012_50120501_50_dialog_content = "¿Debes elegir el momento más extraño para ser competitivo? Vice?",
  ui_story_5012_50120501_51_dialog_content = "Sí, esto no es nada para ser competitivo.",
  ui_story_5012_50120501_52_dialog_content = "Estoy más familiarizado con las calles, así que les daré un minuto de ventaja.",
  ui_story_5012_50120501_53_dialog_content = "¿Realmente vas a convertirlo en una competencia?",
  ui_story_5012_50120501_54_dialog_content = "¡Eso no es necesario, podemos empezar al mismo tiempo!",
  ui_story_5012_50120501_55_dialog_content = "Está bien, pero no me culpes cuando pierdas.",
  ui_story_5012_50120501_56_dialog_content = "Tú tomas esa calle, yo tomaré esta.",
  ui_story_5012_50120501_57_dialog_content = "Nos vemos en la plaza al final.",
  ui_story_5012_50120501_58_dialog_content = "Recuerda que todos sepan que es de mi parte, Lola...!",
  ui_story_5012_50120501_59_dialog_content = "¡Oh, yo tampoco puedo quedarme atrás!",
  ui_story_5012_50120501_60_dialog_content = "¡Te dejo para que entregues estos regalos, PlayerName!",
  ui_story_5012_50120501_61_dialog_content = "Dediqué mucho esfuerzo a traerlos de regreso de Umbraton, ¡así que manéjelos con cuidado!",
  ui_story_5012_50120501_62_dialog_content = "¿Son de Umbraton? Déjeme ver...",
  ui_story_5012_50120501_63_dialog_content = "Colgante de pulpo, campana de perro, casco de leopardo, cuadro de mariposas... Qué colección tan ecléctica.",
  ui_story_5012_50120501_64_dialog_content = "¿También tienes una muñeca de león y una linterna de diente de león?",
  ui_story_5012_50120501_65_dialog_content = "¿No son juguetes tradicionales de Celestita?",
  ui_story_5012_50120501_66_dialog_content = "Supuestamente puedes comprar cualquier cosa en Umbraton. Supongo que eso es cierto.",
  ui_story_5012_50120501_67_dialog_content = "Uh, no tienes que acompañarme... De hecho, me siento avergonzado por eso.",
  ui_story_5012_50120501_68_dialog_content = "Pero eres un VIP de Su Majestad. Absolutamente debo acompañarte.",
  ui_story_5012_50120501_69_dialog_content = "Bueno, está bien... Espera, ¿sabes que la muñeca y la linterna son artículos de Celestita?",
  ui_story_5012_50120501_70_dialog_content = "Northland y Eraveil fueron aliados durante generaciones. No es raro conocer estas cosas.",
  ui_story_5012_50120501_71_dialog_content = "Además, estos adornos de Celestita son buenos accesorios para nuestros árboles resplandecientes.",
  ui_story_5012_50120501_72_dialog_content = "¿Árboles Glimmer? ¿Te refieres a los que están en el patio delantero de cada hogar?",
  ui_story_5012_50120501_73_dialog_content = "Una observación muy astuta. Son abetos de nieve, la variedad de árboles más común en Northland.",
  ui_story_5012_50120501_74_dialog_content = "El abeto de las nieves es también una materia prima para la mayoría de las casas y los muebles, por lo que se ha convertido en un símbolo del hogar y la familia.",
  ui_story_5012_50120501_75_dialog_content = "Cada Año Nuevo, cada hogar erige un árbol que se asemeja a la casa en forma...",
  ui_story_5012_50120501_76_dialog_content = "Siguiendo los adornos y decoraciones, tienes los árboles brillantes ante ti.",
  ui_story_5012_50120501_77_dialog_content = "De hecho, los árboles brillantes realmente se suman al ambiente festivo.",
  ui_story_5012_50120501_78_dialog_content = "Señor. Novio? ¡Estás aquí! ¡Feliz año nuevo!",
  ui_story_5012_50120501_79_dialog_content = "Gracias. Feliz Año Nuevo a ti también. ¿Cómo está la familia?",
  ui_story_5012_50120501_80_dialog_content = "De hecho, me están esquivando ahora mismo.",
  ui_story_5012_50120501_81_dialog_content = "Si estoy en lo cierto, probablemente estén envolviendo tus regalos.",
  ui_story_5012_50120501_82_dialog_content = "Je, es así todos los años. Encontrarían una excusa para conseguirme regalos a mis espaldas.",
  ui_story_5012_50120501_83_dialog_content = "También podría, eso significa que puedo envolver sus regalos cuando estén fuera.",
  ui_story_5012_50120501_84_dialog_content = "Oh, aquí hay algo para ti. ¡Feliz Año Nuevo!",
  ui_story_5012_50120501_85_dialog_content = "¿Una Muñeca Windelion?",
  ui_story_5012_50120501_86_dialog_content = "Solíamos colgar esto cuando era pequeña. ¡Oh, cómo lo extraño!",
  ui_story_5012_50120501_87_dialog_content = "Lo pondré en el árbol ahora mismo. ¡Gracias!",
  ui_story_5012_50120501_88_dialog_content = "Eso es raro... ¿Por qué cuelgan las linternas pero no las encienden?",
  ui_story_5012_50120501_89_dialog_content = "Porque todavía están esperando.",
  ui_story_5012_50120501_90_dialog_content = "¿Para...?",
  ui_story_5012_50120501_91_dialog_content = "hoy es año nuevo Eve, por lo que están esperando hasta el momento adecuado.",
  ui_story_5012_50120501_92_dialog_content = "Encenderán todos los faroles y hogueras con el primer rayo de sol.",
  ui_story_5012_50120501_93_dialog_content = "En correspondencia con el <color=#FFB400>faro</color> que siempre nos ilumina junto al mar.",
  ui_story_5012_50120501_94_dialog_content = "¿Faro junto al mar? ¿Que es eso?",
  ui_story_5012_50120501_95_dialog_content = "Sobre eso, eventualmente lo descubrirás.",
  ui_story_5012_50120501_96_dialog_content = "Huff... Oye, ¿por qué sigues aquí?",
  ui_story_5012_50120501_97_dialog_content = "¡Todos terminamos nuestra ruta!",
  ui_story_5012_50120501_98_dialog_content = "¿Y quién ganó?",
  ui_story_5012_50120501_99_dialog_content = "Los tres llegamos a la meta al mismo tiempo.",
  ui_story_5012_50120501_100_dialog_content = "¡Así que decidimos que quien encuentre PlayerName primero es el ganador!",
  ui_story_5012_50120501_101_dialog_content = "¡Eh, supongo que la victoria me pertenece!",
  ui_story_5012_50120501_102_dialog_content = "Suspiro. Qué pésimo perder...",
  ui_story_5012_50120501_103_dialog_content = "Conozco un lugar muy bueno para esquiar cerca. Veremos quién es el mejor más tarde.",
  ui_story_5012_50120501_104_dialog_content = "Ja, ¿quién es extrañamente competitivo ahora?",
  ui_story_5012_50120501_105_dialog_content = "...",
  ui_story_5012_50120501_106_dialog_content = "Novio! Vengan todos Novio ¡es aquí!",
  ui_story_5012_50120501_107_dialog_content = "Practicaremos villancicos más tarde. Vamos a escuchar Novio ¡contar una historia!",
  ui_story_5012_50120501_108_dialog_content = "¡Muy bien, más Hora de Cuentos!",
  ui_story_5012_50120501_109_dialog_content = "¡Vaya, estamos acosados por niños pequeños!",
  ui_story_5012_50120501_110_dialog_content = "¡Oye, cuántas veces tengo que decirte que no me empujes!",
  ui_story_5012_50120501_111_dialog_content = "Niños, tengo un invitado muy importante al que atender hoy.",
  ui_story_5012_50120501_112_dialog_content = "Pero hemos estado esperando esto...",
  ui_story_5012_50120501_113_dialog_content = "¡Sí! ¿Ves lo bien que decoramos los árboles brillantes para esto?",
  ui_story_5012_50120501_114_dialog_content = "Y hemos estado practicando villancicos muy duro...",
  ui_story_5012_50120501_115_dialog_content = "no te preocupes por mi, Novio, y me encantaría escucharte contar una historia también.",
  ui_story_5012_50120501_116_dialog_content = "Bueno, ya que incluso PlayerName solicitó...",
  ui_story_5012_50120501_117_dialog_content = "¡Está bien! ¡Gracias, PlayerName!",
  ui_story_5012_50120501_118_dialog_content = "Déjame pensar, ¿dónde lo dejé la última vez...?",
  ui_story_5012_50120501_119_dialog_content = "De acuerdo, todos los soberanos de Northland deben abandonar muchas cosas antes de convertirse en un verdadero gobernante.",
  ui_story_5012_50120501_120_dialog_content = "Abandonaron lo que más apreciaban...",
  ui_story_5012_50120501_121_dialog_content = "Abandonaron los nombres que tenían desde su nacimiento.",
  ui_story_5012_50120501_122_dialog_content = "Abandonaron la libertad personal, atando para siempre el destino de Northland al suyo.",
  ui_story_5012_50120501_123_dialog_content = "Solo haciendo eso ganarían la fuerza para defender Northland.",
  ui_story_5012_50120501_124_dialog_content = "En cuanto a nuestra Reina Bethlehem hoy en día...",
  ui_story_5012_50120501_125_dialog_content = "Tiene una mente abierta que no se parece a ningún otro gobernante de nuestra historia.",
  ui_story_5012_50120501_126_dialog_content = "Pero incluso ella tuvo que sufrir la metamorfosis.",
  ui_story_5012_50120501_127_dialog_content = "En el momento...",
  ui_story_5012_50120601_1_dialog_content = "En ese momento, Su Majestad me sometió sin piedad a un riguroso entrenamiento.",
  ui_story_5012_50120601_2_dialog_content = "Ella me enseñó mucho. Tiene la equidad y la determinación esenciales para un gran líder.",
  ui_story_5012_50120601_3_dialog_content = "De sus instrucciones, aprendí a blandir una espada y también a blandir un cetro.",
  ui_story_5012_50120601_4_dialog_content = "Sin embargo, en retrospectiva, no la entendí realmente.",
  ui_story_5012_50120601_5_dialog_content = "Carleen...",
  ui_story_5012_50120601_6_dialog_content = "Esa fue también la primera vez que vi a la Reina desde la perspectiva de un historiador.",
  ui_story_5012_50120601_7_dialog_content = "Hay pocos libros en Northland y los documentos históricos son especialmente raros.",
  ui_story_5012_50120601_8_dialog_content = "Cuando vivía en Northland, confiaba en relatos verbales y en mi propia imaginación para reconstruir el pasado.",
  ui_story_5012_50120601_9_dialog_content = "¿Cuentas verbales?",
  ui_story_5012_50120601_10_dialog_content = "No me diga que su...",
  ui_story_5012_50120601_11_dialog_content = "<color=#e8d9bb>Toc, toc.</color>",
  ui_story_5012_50120601_12_dialog_content = "Por favor entra.",
  ui_story_5012_50120601_13_dialog_content = "Saludos, PlayerName.",
  ui_story_5012_50120601_14_dialog_content = "Eso es oportuno.",
  ui_story_5012_50120601_15_dialog_content = "¿Te vas a jubilar?",
  ui_story_5012_50120601_16_dialog_content = "Aún no.",
  ui_story_5012_50120601_17_dialog_content = "Los Celestitas deben tener una mucha resistencia.",
  ui_story_5012_50120601_18_dialog_content = "No, lo entendiste mal.",
  ui_story_5012_50120601_19_dialog_content = "En este momento del pasado, siempre pasé solo en el Colossus.",
  ui_story_5012_50120601_20_dialog_content = "Dormiría durante las noches de invierno.",
  ui_story_5012_50120601_21_dialog_content = "Así que no quiero que el día de hoy termine tan rápido.",
  ui_story_5012_50120601_22_dialog_content = "Ya veo. Es un gran honor para mí haber sido parte de este día para ustedes.",
  ui_story_5012_50120601_23_dialog_content = "¿Te interesa el último evento de Año Nuevo?",
  ui_story_5012_50120601_24_dialog_content = "¿Qué es?",
  ui_story_5012_50120601_25_dialog_content = "Según el calendario de Northland, hoy es el último día de Año Nuevo, además de un día muy especial.",
  ui_story_5012_50120601_26_dialog_content = "Hoy es la <color=#FFB400>Noche Polar</color>.",
  ui_story_5012_50120601_27_dialog_content = "¿Noche Polar?",
  ui_story_5012_50120601_28_dialog_content = "Debido a los materiales especiales utilizados en su construcción, el Palacio de Invierno sigue brillando de forma natural incluso sin estar expuesto a una fuente de luz fuerte.",
  ui_story_5012_50120601_29_dialog_content = "Por eso nunca notó la anomalía.",
  ui_story_5012_50120601_30_dialog_content = "Es una costumbre de Northland que la gente se quede despierta toda la noche para presenciar el primer rayo de sol del año nuevo.",
  ui_story_5012_50120601_31_dialog_content = "La espera también representa soportar la oscuridad y dirigirse hacia la luz.",
  ui_story_5012_50120601_32_dialog_content = "Eso suena muy inspirador.",
  ui_story_5012_50120601_33_dialog_content = "Si estás interesado, déjame llevarte a <color=#FFB400>Lago Espejo</color>.",
  ui_story_5012_50120601_34_dialog_content = "¿Lago Espejo? ¿No hará mucho frío alrededor del lago?",
  ui_story_5012_50120601_35_dialog_content = "Su Majestad me indicó que le recuerde que debe hacer la preparación adecuada.",
  ui_story_5012_50120601_36_dialog_content = "¿Significa que estás aquí por orden de la Reina?",
  ui_story_5012_50120601_37_dialog_content = "Sí, Su Majestad me envió. De lo contrario, no me habría entrometido.",
  ui_story_5012_50120601_38_dialog_content = "En ese caso.",
  ui_story_5012_50120601_39_dialog_content = "...",
  ui_story_5012_50120601_40_dialog_content = "Okey, okey, entiendo...",
  ui_story_5012_50120601_41_dialog_content = "Por favor sígueme.",
  ui_story_5012_50120601_42_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5012_50120601_43_dialog_content = "Aquí, por fin.",
  ui_story_5012_50120601_44_dialog_content = "Esperemos un rato aquí. Debería ver a Su Majestad pronto.",
  ui_story_5012_50120601_45_dialog_content = "Por supuesto, también puedo pasear por el lago contigo.",
  ui_story_5012_50120601_46_dialog_content = "Este Lago Espejo hace honor a su nombre. Fíjese en la claridad de sus reflejos.",
  ui_story_5012_50120601_47_dialog_content = "No solo eso, también es un espejo de dos caras: una para dar la bienvenida al futuro, la otra porta el pasado.",
  ui_story_5012_50120601_48_dialog_content = "Si miras fijamente a la superficie, te iluminará.",
  ui_story_5012_50120601_49_dialog_content = "Iluminame...",
  ui_story_5012_50120601_50_dialog_content = "...",
  ui_story_5012_50120601_51_dialog_content = "...",
  ui_story_5012_50120601_52_dialog_content = "¡Vamos, ponte al día conmigo rápidamente!",
  ui_story_5012_50120601_53_dialog_content = "¡Solo nos queda un poco más y podemos comprar adornos de árboles brillantes de la caravana!",
  ui_story_5012_50120601_54_dialog_content = "¿Qué?",
  ui_story_5012_50120601_55_dialog_content = "¿Me estas llamando?",
  ui_story_5012_50120601_56_dialog_content = "¡Sí! Pero, reduzca el trote, <color=#FFB400>Shaya</color>, alteza.",
  ui_story_5012_50120601_57_dialog_content = "¿Y quién es ese extranjero que está a tu lado, aturdido y confundido?",
  ui_story_5012_50120601_58_dialog_content = "¿Estás hablando de mí?",
  ui_story_5012_50120601_59_dialog_content = "Esta vez sí. ¡¿Eres Celestita?!",
  ui_story_5012_50120601_60_dialog_content = "¡Observación astuta! Espera un minuto...",
  ui_story_5012_50120601_61_dialog_content = "Esta no es la Northland en la que estaba hace un momento.",
  ui_story_5012_50120601_62_dialog_content = "¿Es esta niña que veo...?",
  ui_story_5012_50120601_63_dialog_content = "Lo has adivinado, PlayerName.",
  ui_story_5012_50120601_64_dialog_content = "ella es reina Bethlehem en su infancia, aunque su nombre en ese momento era <color=#FFB400>Shaya</color>.",
  ui_story_5012_50120601_65_dialog_content = "¡Vamos, apresura!",
  ui_story_5012_50120601_66_dialog_content = "Conseguí los adornos, ¡pero aún tenemos que terminar de decorar el árbol antes del atardecer!",
  ui_story_5012_50120601_67_dialog_content = "¡Me voy si te quedas ahí parado!",
  ui_story_5012_50120601_68_dialog_content = "¿Qué pasa? ¿Alguien me puede decir, por favor?",
  ui_story_5012_50120601_69_dialog_content = "Oh no, ¿qué es eso?",
  ui_story_5012_50120601_70_dialog_content = "¡Ayuda!",
  ui_story_5012_50120601_71_dialog_content = "¿Qué está pasando?",
  ui_story_5012_50120601_72_dialog_content = "Oh no...",
  ui_story_5012_50120601_73_dialog_content = "<size=50>¡Rarrr!</size>",
  ui_story_5012_50120601_74_dialog_content = "¿Eclipsite? ¿Aquí?",
  ui_story_5012_50120601_75_dialog_content = "Novio, Caelestite, ¡vamos a comprobarlo!",
  ui_story_5012_50120602_1_dialog_content = "Resoplan...",
  ui_story_5012_50120602_2_dialog_content = "¡No puedo creer que Eclipsite fuera tan alta!",
  ui_story_5012_50120602_3_dialog_content = "Incluso dudé cuando desenvainé mi espada.",
  ui_story_5012_50120602_4_dialog_content = "Lo hizo muy bien, alteza.",
  ui_story_5012_50120602_5_dialog_content = "¿Crees que sí? ¿Parecía un valiente norteño, Novio?",
  ui_story_5012_50120602_6_dialog_content = "¡Claro!",
  ui_story_5012_50120602_7_dialog_content = "Esas horribles abominaciones nunca deberían haber estado aquí en primer lugar.",
  ui_story_5012_50120602_8_dialog_content = "Salvaste toda la calle.",
  ui_story_5012_50120602_9_dialog_content = "Gracias por tu ayuda también, PlayerName.",
  ui_story_5012_50120602_10_dialog_content = "Espero que no te hayan asustado con su presencia inesperada.",
  ui_story_5012_50120602_11_dialog_content = "No estaba asustado. Y solo ayudé un poco.",
  ui_story_5012_50120602_12_dialog_content = "Por favor sé honesto conmigo, Novio.",
  ui_story_5012_50120602_13_dialog_content = "¿Por qué hay Eclipsites en Northland de repente?",
  ui_story_5012_50120602_14_dialog_content = "No necesitan otra razón que no sea que alguien las ordene.",
  ui_story_5012_50120602_15_dialog_content = "No eso está mal. ¡Deberías conocer la razón mejor que yo!",
  ui_story_5012_50120602_16_dialog_content = "Northland necesita un gobernante, y solo el gobernante puede obligar al <color=#FFB400>Sanctum</color> a reanudar la protección de Northland.",
  ui_story_5012_50120602_17_dialog_content = "Princesa Shaya...",
  ui_story_5012_50120602_18_dialog_content = "Es... es Srta. Shaya...",
  ui_story_5012_50120602_19_dialog_content = "¡Por el Norte! Gracias por rescatarnos, Srta. Shaya ...",
  ui_story_5012_50120602_20_dialog_content = "Cuando Srta. Shaya ascienda al trono, seguramente regresaremos a tiempos de paz una vez más ...",
  ui_story_5012_50120602_21_dialog_content = "¿El trono? ¿Estás bromeando?",
  ui_story_5012_50120602_22_dialog_content = "¡Una niña como ella no tiene lugar en el trono de un reino!",
  ui_story_5012_50120602_23_dialog_content = "¿Cómo podría un simple niño soportar el poder y la responsabilidad de la <color=#FFB400>Chispa</color>?",
  ui_story_5012_50120602_24_dialog_content = "Pero es la única forma ... ¿No es así?",
  ui_story_5012_50120602_25_dialog_content = "Solo mira, el fuego en el <color=#FFB400>Faro</color> que siempre ha estado encendido se ha apagado ... Northland ya no es seguro.",
  ui_story_5012_50120602_26_dialog_content = "Si Srta. Shaya no hereda la Chispa, ¿se contentarán con acobardarse en sus casas por el resto de sus vidas?",
  ui_story_5012_50120602_27_dialog_content = "No les hagas caso, Srta. Shaya. Solo necesitas escuchar tu propio corazón ...",
  ui_story_5012_50120602_28_dialog_content = "Entiendo, Novio... No hay necesidad de decir más.",
  ui_story_5012_50120602_29_dialog_content = "Vamos, debemos apresurarnos a Lago Espejo.",
  ui_story_5012_50120602_30_dialog_content = "También deberíamos traer \"esas cosas\" con nosotros ... ¿No estás de acuerdo?",
  ui_story_5012_50120602_31_dialog_content = "Tú ... Ya lo has decidido, ¿no?",
  ui_story_5012_50120602_32_dialog_content = "Ven, partamos.",
  ui_story_5012_50120602_33_dialog_content = "Ya sabes... A veces Shaya no se parece en nada a un niño pequeño ...",
  ui_story_5012_50120602_34_dialog_content = "Deberías venir tú también, Lord PlayerName.",
  ui_story_5012_50120602_35_dialog_content = "Estoy seguro de que todavía albergas dudas y estaré más que feliz de abordarlas.",
  ui_story_5012_50120602_36_dialog_content = "Desafortunadamente, después de ver un Eclipsite ... Podemos estar seguros de que ya se han infiltrado más en Northland.",
  ui_story_5012_50120602_37_dialog_content = "Todos deberíamos mantenernos concentrados y estar aún más vigilantes.",
  ui_story_5012_50120602_38_dialog_content = "Me alivia oírte decir eso.",
  ui_story_5012_50120602_39_dialog_content = "Creo que necesitaremos sus habilidades en el camino que tenemos por delante.",
  ui_story_5012_50120702_1_dialog_content = "<size=45>¡¡¡Roooaaar!!!</size>",
  ui_story_5012_50120702_2_dialog_content = "Fuerza de Invierno...",
  ui_story_5012_50120702_3_dialog_content = "Graah...",
  ui_story_5012_50120702_4_option_content = "Control forzado",
  ui_story_5012_50120702_5_dialog_content = "Podemos relajarnos por el momento. Parece que fue la última Eclipsite en las cercanías de Lago Espejo.",
  ui_story_5012_50120702_6_dialog_content = "Es posible que hayamos eliminado a los Eclipsites antes que nosotros, pero estoy seguro de que hay muchos más fuera de nuestra vista, causando estragos en nuestros compatriotas ...",
  ui_story_5012_50120702_7_dialog_content = "Nos estamos quedando sin tiempo.",
  ui_story_5012_50120702_8_dialog_content = "En cualquier caso... Has sido de ayuda para Northland, Celestita.",
  ui_story_5012_50120702_9_dialog_content = "Siento que debería expresar mi gratitud a la manera habitual de Northland, pero tengo asuntos aún más urgentes entre manos.",
  ui_story_5012_50120702_10_dialog_content = "Como tal ... ¡dejaré esto en manos de Novio!",
  ui_story_5012_50120702_11_dialog_content = "* Suspiro * Srta. Shaya ... ¿Podría ser que esté avergonzada?",
  ui_story_5012_50120702_12_dialog_content = "...",
  ui_story_5012_50120702_13_dialog_content = "* Risas * Entonces, sigue tu camino, Srta. Shaya. Todavía tengo mucho que discutir con Lord PlayerName.",
  ui_story_5012_50120702_14_dialog_content = "Pero antes de partir ... Permítame decir algunas palabras más.",
  ui_story_5012_50120702_15_dialog_content = "Respeto todas y cada una de las elecciones que hagas, porque no importa cómo decidas proceder ... Cada elección que hagas tendrá un impacto en el destino de todo Northland de alguna manera, forma o forma.",
  ui_story_5012_50120702_16_dialog_content = "Así que, por favor, no se obligue a hacer nada de lo que pueda arrepentirse en el futuro ...",
  ui_story_5012_50120702_17_dialog_content = "Puedes ser tan insoportablemente indeciso a veces, Novio!",
  ui_story_5012_50120702_18_dialog_content = "No tengo que tomar ninguna decisión aquí.",
  ui_story_5012_50120702_19_dialog_content = "¿Podría por favor explicar todo lo que ha sucedido hasta ahora, Novio? Desde el principio...",
  ui_story_5012_50120702_20_dialog_content = "Además, ¿por qué hemos venido a Lago Espejo?",
  ui_story_5012_50120702_21_dialog_content = "No vas a hacer que me vuelva a mirar al espejo, ¿verdad ...?",
  ui_story_5012_50120702_22_dialog_content = "Así es precisamente como aparece, Lord PlayerName. Lo que estás presenciando es el pasado de la reina Bethlehem, antes de su ascensión al trono de Northland.",
  ui_story_5012_50120702_23_dialog_content = "Cuando llega el momento de cambiar las reglas, el poder de <color=#FFB400>Chispa</color> deja de estar disponible temporalmente.",
  ui_story_5012_50120702_24_dialog_content = "Es durante estos tiempos cuando Northland es más vulnerable, y el reino debe confiar en la protección de los",
  ui_story_5012_50120702_25_dialog_content = "Así que esos Eclipsites hace un momento ... ¿Se estaban aprovechando de la pérdida temporal de protección para invadir Northland?",
  ui_story_5012_50120702_26_dialog_content = "De hecho ... Por insensatos que parezcan, parecería que son particularmente conscientes de esta faceta de la existencia de nuestro reino.",
  ui_story_5012_50120702_27_dialog_content = "Hasta que aparezca un sucesor al trono, Northland permanecerá en este estado de miedo y peligro constantes.",
  ui_story_5012_50120702_28_dialog_content = "Además, el poder del Chispa solo se ofrecerá a Northland, y no a ningún individuo específico.",
  ui_story_5012_50120702_29_dialog_content = "Para heredar el poder de la Chispa, primero hay que abandonar por completo el sentido de sí mismo y dedicar su corazón y su alma a la preservación de toda la Northland ...",
  ui_story_5012_50120702_30_dialog_content = "creo que la reina Bethlehem ya ha llegado a ese estado mental.",
  ui_story_5012_50120702_31_dialog_content = "Estoy de acuerdo. La reina Bethlehem ves ante ti en este momento es el mejor heredero posible de la Chispa.",
  ui_story_5012_50120702_32_dialog_content = "Al crecer, Su Majestad nunca tuvo amigos de la misma edad que ella. Me considero una de las pocas personas que la comprende un poco.",
  ui_story_5012_50120702_33_dialog_content = "Pero sólo ahora que recuerdo esta vez me doy cuenta de que Su Majestad siempre ha tenido una determinación y una convicción tan firmes.",
  ui_story_5012_50120702_34_dialog_content = "Tan inmensa resolución ... Es como si ella hubiera nacido con eso.",
  ui_story_5012_50120702_35_dialog_content = "En este sentido, ella es diferente a todos los reyes que he hecho en el pasado.",
  ui_story_5012_50120702_36_dialog_content = "Mira ante ti ...",
  ui_story_5012_50120702_37_dialog_content = "Al mirarse en el espejo esta noche, Su Majestad le ha permitido vislumbrar su propio pasado.",
  ui_story_5012_50120702_38_dialog_content = "Y ahora mismo, para prepararse para su rito de ascensión al trono, busca abandonar una parte de sí misma en el pasado ... La parte de sí misma llamada \"Shaya\".",
  ui_story_5012_50120702_39_option_content = "Así que esto es lo que está pasando",
  ui_story_5012_50120702_40_dialog_content = "Y también es casi la hora.",
  ui_story_5012_50120702_41_option_content = "Todavía no entiendo...",
  ui_story_5012_50120702_42_dialog_content = "Entonces, ¿por qué no nos acercamos y echamos un vistazo?",
  ui_story_5012_50120702_43_dialog_content = "Ven, esperemos junto al borde del Lago Espejo.",
  ui_story_5012_50120702_44_dialog_content = "...",
  ui_story_5012_50120702_45_dialog_content = "Srta. Shaya, ¿ya terminaste de despedirte de tus amigos de juguete?",
  ui_story_5012_50120702_46_dialog_content = "¿Eh? Oh, lo hiciste...",
  ui_story_5012_50120702_47_dialog_content = "¡Yo-yo no estaba haciendo nada por el estilo! ¡Simplemente los estaba organizando todos antes de irnos!",
  ui_story_5012_50120702_48_dialog_content = "¿Son todos estos ... juguetes?",
  ui_story_5012_50120702_49_dialog_content = "(\"Abandonando la parte de ella llamada Shaya...\" ¿Podría ser esto lo que Novio ¿quiso decir?)",
  ui_story_5012_50120702_50_dialog_content = "Son chucherías sin sentido, ¡nada más! Incluyendo ... Este.",
  ui_story_5012_50120702_51_dialog_content = "Es un reloj de arena muy bonito, ¿no?",
  ui_story_5012_50120702_52_dialog_content = "De hecho, y también es la posesión más querida de Srta. Shaya.",
  ui_story_5012_50120702_53_dialog_content = "Por favor, deseche este junto con los otros también, Novio.",
  ui_story_5012_50120702_54_dialog_content = "...",
  ui_story_5012_50120702_55_dialog_content = "... Está hecho, Srta. Shaya. Creo que eso es todo ahora.",
  ui_story_5012_50120702_56_dialog_content = "Comprendo.",
  ui_story_5012_50120702_57_dialog_content = "Ahora bien, Srta. Shaya ... Por favor, mire de cerca la superficie del Lago Espejo ...",
  ui_story_5012_50120702_58_dialog_content = "\"Por lo tanto, los recuerdos del pasado serán olvidados ...\"",
  ui_story_5012_50120702_59_dialog_content = "\"Que el gran y antiguo poder de nuestra tierra pueda despertar una vez más ...\"",
  ui_story_5012_50120702_60_dialog_content = "\"Un alma más pura, ofrecida en su totalidad por todo Northland, espera la creación de un nuevo pacto ...\"",
  ui_story_5012_50120702_61_dialog_content = "<color=#e8d9bb>Bwooommm... Bwooommm...</color>",
  ui_story_5012_50120702_62_dialog_content = "Ah ... Se ha hecho sonar la bocina del Palacio de Invierno.",
  ui_story_5012_50120702_63_dialog_content = "Por favor, ven con nosotros, Lord PlayerName. La ceremonia de sucesión de nuestro nuevo gobernante está cerca de nosotros.",
  ui_story_5012_50120702_64_dialog_content = "¿Estás preparada, Princesa Heredera de Northland?",
  ui_story_5012_50120702_65_dialog_content = "Sí lo soy, señor Novio.",
  ui_story_5012_50120801_1_dialog_content = "<color=#e8d9bb>Bwooommm... Bwooommm...</color>",
  ui_story_5012_50120801_2_dialog_content = "Estas personas ... ¿Van de camino al Palacio de Invierno, como nosotros?",
  ui_story_5012_50120801_3_dialog_content = "Correcto. Lo que has escuchado dos veces ahora es el sonido del cuerno del Palacio de Invierno, algo que rara vez se escucha en nuestro reino.",
  ui_story_5012_50120801_4_dialog_content = "Cuando suena el cuerno, indica que algo monumental está sucediendo dentro de los muros del Palacio de Invierno.",
  ui_story_5012_50120801_5_dialog_content = "Desde que nuestro monarca anterior dejó el trono de Northland, la gente ha esperado ansiosamente el sonido del cuerno.",
  ui_story_5012_50120801_6_dialog_content = "Supongo que nadie desea dejar pasar la oportunidad de presenciar la coronación de nuestro nuevo gobernante.",
  ui_story_5012_50120801_7_dialog_content = "...",
  ui_story_5012_50120801_8_dialog_content = "Las puertas del Palacio de Invierno ya deberían estar abiertas para que todos puedan entrar.",
  ui_story_5012_50120801_9_dialog_content = "De hecho, princesa heredera ... ¿Pero qué es esto? ¿Estás sudando?",
  ui_story_5012_50120801_10_dialog_content = "Hay demasiada gente abarrotando las calles. Por favor, agárrese fuerte de mi manga, Srta. Shaya.",
  ui_story_5012_50120801_11_dialog_content = "Novio, has enseñado a muchos reyes y reinas. ¿De qué hablaron camino a sus coronaciones?",
  ui_story_5012_50120801_12_dialog_content = "No hay necesidad de disimular sus preocupaciones, Srta. Shaya. Puedes hablar conmigo libremente.",
  ui_story_5012_50120801_13_dialog_content = "Muy bien, Maestro Novio ... ¿Recuerda cuando tenía unos cinco años, cómo solía sermonearme sobre la larga historia de Northland?",
  ui_story_5012_50120801_14_dialog_content = "Pues sí, mi señora. De hecho, recuerdo claramente un caso en el que te escapaste frustrado y te escondiste en las profundidades del bosque. Busqué entre la nieve y los árboles durante horas ese día.",
  ui_story_5012_50120801_15_dialog_content = "Y más tarde, después de haber estudiado el manejo de la espada ... ¡incluso pude cortar los cristales de Pino de Northland con facilidad!",
  ui_story_5012_50120801_16_dialog_content = "De hecho, Srta. Shaya. Incluso guardaste un fragmento de uno de esos cristales y me lo regalaste para mi cumpleaños.",
  ui_story_5012_50120801_17_dialog_content = "Y luego, para compensarme por mi regalo ... Me diste un juguete.",
  ui_story_5012_50120801_18_dialog_content = "Ah ... No hay necesidad de decir nada más, Srta. Shaya. Ese reloj de arena no tenía ningún valor especial; no era más que un pequeño regalo, nada más.",
  ui_story_5012_50120801_19_dialog_content = "En ese momento, era bastante popular entre los niños de Pueblo maravilloso. Simplemente pensé que tú también lo disfrutarías.",
  ui_story_5012_50120801_20_dialog_content = "Los niños de Northland a menudo encuentran formas únicas de entretenerse ...",
  ui_story_5012_50120801_21_dialog_content = "Contar acertijos en Lago Espejo, o correr de un lado a otro de Pinefrost Gorge ... Ellos realmente saben cómo divertirse, ¿no es así?",
  ui_story_5012_50120801_22_dialog_content = "Para que no lo olvide, mi señora ... Usted también es una niña.",
  ui_story_5012_50120801_23_dialog_content = "...",
  ui_story_5012_50120801_24_dialog_content = "Espera...",
  ui_story_5012_50120801_25_dialog_content = "<size=45><color=#e8d9bb>Boom...</color></size>",
  ui_story_5012_50120801_26_dialog_content = "... ¡¿Qué fue ese ruido hace un momento?!",
  ui_story_5012_50120801_27_dialog_content = "¡Graaaaaagh!",
  ui_story_5012_50120801_28_dialog_content = "¡Gahhhh!",
  ui_story_5012_50120801_28X1_dialog_content = "¡Incluso la capital ya ha...!",
  ui_story_5012_50120801_28X2_dialog_content = "Si las cosas siguen así...",
  ui_story_5012_50120801_29_dialog_content = "Un \"niño\" ... Nunca podría proteger todo Northland.",
  ui_story_5012_50120801_30_dialog_content = "El único que puede bendecir a Northland con paz y protección una vez más... es \"<color=#FFB400>Bethlehem</color>.\"",
  ui_story_5012_50120901_1_dialog_content = "Estos Eclipsites ... Nos siguieron hasta el Palacio de Invierno ...",
  ui_story_5012_50120901_2_dialog_content = "Esto no es bueno ... Va a tomar tiempo deshacerse de todos ellos ...",
  ui_story_5012_50120901_3_dialog_content = "Novio, por favor ayude a evacuar a las personas en nuestra vecindad inmediata.",
  ui_story_5012_50120901_4_dialog_content = "Yo mismo moleré estos Eclipsites hasta convertirlos en polvo.",
  ui_story_5012_50120901_5_dialog_content = "El claxon sigue sonando, milady. No debe detenerse por ningún motivo.",
  ui_story_5012_50120901_6_dialog_content = "Nunca ha habido un monarca en nuestra historia que se haya atrevido a interrumpir los trámites de la coronación.",
  ui_story_5012_50120901_7_dialog_content = "Pero, ¿cómo podemos hacer la vista gorda ante el peligro y la destrucción que amenazan a nuestro pueblo?",
  ui_story_5012_50120901_8_dialog_content = "¡Toda esta ceremonia no significa nada si nuestra tierra y nuestra gente deben sufrir por ella!",
  ui_story_5012_50120901_9_dialog_content = "... Muy bien, mi señora ...",
  ui_story_5012_50120901_10_dialog_content = "<size=45>¡¡¡Graaauuugh!!!</size>",
  ui_story_5012_50120901_11_dialog_content = "¡¡¡Aurora's Edge!!!",
  ui_story_5012_50120901_12_dialog_content = "Reina Beth ... ¡Quiero decir, Srta. Shaya! ¡Detrás de ti!",
  ui_story_5012_50120901_13_dialog_content = "Ngh ... Qué problemático.",
  ui_story_5012_50120901_14_dialog_content = "Extremadamente frío...",
  ui_story_5012_50120901_15_dialog_content = "Graaagh ...",
  ui_story_5012_50120901_16_dialog_content = "Las puertas del Palacio de Invierno han sido selladas por el momento, Srta. Shaya. Todos los supervivientes cercanos se han refugiado dentro de sus muros.",
  ui_story_5012_50120901_17_dialog_content = "Sin embargo ... Si los Eclipsites continúan con su asedio interminable del Palacio de Invierno, es solo cuestión de tiempo antes de que lo logren.",
  ui_story_5012_50120901_18_dialog_content = "Nuestra única esperanza es que obtengas rápidamente el poder de la <color=#FFB400>Chispa</color> y reactives el <color=#FFB400>Santuario</color> para librar a Northland de su malvada presencia ...",
  ui_story_5012_50120901_19_dialog_content = "Entonces, y solo entonces, se restablecerá la paz y la seguridad en nuestras tierras.",
  ui_story_5012_50120901_20_dialog_content = "...",
  ui_story_5012_50120901_21_dialog_content = "Entiendo.",
  ui_story_5012_50120901_22_dialog_content = "Venir, Novio... Y tú también, Caelestite. Vamos adentro.",
  ui_story_5012_50120901_23_dialog_content = "Srta. Shaya ... La futura reina ...",
  ui_story_5012_50120901_24_dialog_content = "Mi señora ... El trono ha esperado por mucho tiempo su llegada.",
  ui_story_5012_50120901_25_dialog_content = "A partir de este día, les ofrecemos nada menos que nuestra fe y fidelidad inquebrantables.",
  ui_story_5012_50120901_26_dialog_content = "No hay necesidad de ser tan rígido en sus creencias, buena gente de Northland. El mundo cambia con cada día que pasa, y también nuestras costumbres ...",
  ui_story_5012_50120901_27_dialog_content = "Sin embargo, nunca debemos olvidar elogiar Northland, la tierra de nuestro nacimiento.",
  ui_story_5012_50120901_28_dialog_content = "Porque Northland nos da vida y nos sostiene hasta nuestro último aliento. La tierra es nuestra madre y nosotros sus hijos.",
  ui_story_5012_50120901_29_dialog_content = "¡Por el Norte! ¡Vivimos por Northland!",
  ui_story_5012_50120901_30_dialog_content = "¡Por el Norte! ¡Vivimos por Northland!",
  ui_story_5012_50120901_31_dialog_content = "La ceremonia de coronación ha comenzado de nuevo, milady.",
  ui_story_5012_50120901_32_dialog_content = "No hay vuelta atrás ahora. Sube los escalones hacia el trono y reclama el poder de la Chispa.",
  ui_story_5012_50120901_33_dialog_content = "...",
  ui_story_5012_50120901_34_dialog_content = "Novio...",
  ui_story_5012_50120901_35_dialog_content = "Seguir.",
  ui_story_5012_50120901_36_dialog_content = "¡Sí...!",
  ui_story_5012_50120901_37_dialog_content = "<color=#e8d9bb>¡Bang...!</color>",
  ui_story_5012_50120901_38_dialog_content = "¡Los monstruos! Ellos ... ¡Se han abierto paso!",
  ui_story_5012_50120901_39_dialog_content = "NORTE-Novio?!",
  ui_story_5012_50120901_40_dialog_content = "¡El tiempo no está de nuestro lado! Recuerde, mi señora: ¡ahora no hay vuelta atrás!",
  ui_story_5012_50120901_41_dialog_content = "En cuanto a estos intrusos ...",
  ui_story_5012_50120901_42_dialog_content = "¡Déjanos a nosotros!",
  ui_story_5012_50120902_1_dialog_content = "Estamos salvados ...",
  ui_story_5012_50120902_2_dialog_content = "Parece que nos hemos ocupado de todos los Eclipsite cercanos ...",
  ui_story_5012_50120902_3_dialog_content = "Me pregunto cómo estará Shaya ...",
  ui_story_5012_50120902_4_dialog_content = "Compruébelo usted mismo, Lord PlayerName.",
  ui_story_5012_50120902_5_dialog_content = "La chispa se ha reavivado ...",
  ui_story_5012_50120902_6_dialog_content = "Tómese un momento para apreciar esta ocasión trascendental.",
  ui_story_5012_50120902_7_dialog_content = "<color=#e8d9bb>En el Palacio de Invierno, junto al trono ...</color>",
  ui_story_5012_50120902_8_dialog_content = "La nieve derretida lleva agua a través de montañas y arroyos, dando vida a esta tierra bendita.",
  ui_story_5012_50120902_9_dialog_content = "Mientras un trueno rompe el silencio a través de la tierra, un fuego rugiente quema lo que se ha secado y muerto.",
  ui_story_5012_50120902_10_dialog_content = "Esta luz eterna y gloriosa brilla hoy ante usted, Su Majestad. Como tu humilde subordinado, te pido que levantes la cabeza para enfrentarlo.",
  ui_story_5012_50120902_11_dialog_content = "Porque así como la familia real elige a Chispa, también Chispa elige a su sucesor.",
  ui_story_5012_50120902_12_dialog_content = "Antes de heredar el poder de Chispa, hay una última cosa que debes hacer tú, y solo tú.",
  ui_story_5012_50120902_13_dialog_content = "Su Majestad ... Por favor, recite el juramento real como ofrenda a la Chispa.",
  ui_story_5012_50120902_14_dialog_content = "...",
  ui_story_5012_50120902_15_dialog_content = "La espada y el cetro siempre han sido símbolos de poder absoluto en esta tierra.",
  ui_story_5012_50120902_16_dialog_content = "Se puede conquistar una nación utilizando una u otra.",
  ui_story_5012_50120902_17_dialog_content = "Pero en los reinos del sur, donde la nieve blanca y pura no cubre la tierra ...",
  ui_story_5012_50120902_18_dialog_content = "Ya hay suficientes luchas y conflictos.",
  ui_story_5012_50120902_19_dialog_content = "Juro aceptar el poder de Chispa y llevar a Northland a una era larga y próspera de paz y tranquilidad.",
  ui_story_5012_50120902_20_dialog_content = "\"Para el norte, para la familia y el país\".",
  ui_story_5012_50120902_21_dialog_content = "En el nombre de Bethlehem¡Juro en este momento usar el poder de la Chispa en la protección de toda Northland!",
  ui_story_5012_50120902_22_dialog_content = "Luego, en nombre de los reyes y reinas del pasado, la gente de Northland y el vasto e ilimitado invierno ...",
  ui_story_5012_50120902_23_dialog_content = "Te nombro Monarca de Northland y Protector de la Chispa... Su Majestad, Reina Bethlehem!",
  ui_story_5012_50120902_24_dialog_content = "<size=45>¡Larga vida a la reina!</size>",
  ui_story_5012_50120902_25_dialog_content = "<color=#e8d9bb>Y así, la joven reina levanta la cabeza, como si escuchara los susurros de un gran y antiguo poder ...</color>",
  ui_story_5012_50120902_26_dialog_content = "La Chispa finalmente te ha elegido. Lo has hecho bien...",
  ui_story_5012_50120902_27_dialog_content = "Reina Bethlehem.",
  ui_story_5012_50120902_28_dialog_content = "Gracias, Novio.",
  ui_story_5012_50121001_1_dialog_content = "Northland lleva mucho tiempo esperando la llegada de su reina, Su Majestad.",
  ui_story_5012_50121001_2_dialog_content = "...",
  ui_story_5012_50121001_3_dialog_content = "¿Cómo podría ...?",
  ui_story_5012_50121001_4_dialog_content = "¡¿Cómo pudo haber cambiado tanto en un instante ?!",
  ui_story_5012_50121001_5_dialog_content = "¿Esto realmente está sucediendo ahora mismo?",
  ui_story_5012_50121001_6_dialog_content = "Bueno, no ... es una visión del pasado, después de todo ...",
  ui_story_5012_50121001_7_dialog_content = "Nunca olvides este momento: el momento en el que el poder de defender Northland despertó desde tu antiguo y real linaje.",
  ui_story_5012_50121001_8_dialog_content = "La Chispa, que se asienta sobre el trono de nuestro reino, ha ardido desde el comienzo de nuestra civilización.",
  ui_story_5012_50121001_9_dialog_content = "Den gracias a ella ya sus antecedentes, porque es por su protección que nuestra tierra helada da vida a sus habitantes.",
  ui_story_5012_50121001_10_dialog_content = "Hoy, las nubes oscuras arriba comienzan a disiparse,\nMientras la Reina de Northland toma su trono una vez más.",
  ui_story_5012_50121001_11_dialog_content = "¿Y qué me pediría Northland ahora?",
  ui_story_5012_50121001_12_dialog_content = "Te pedimos humildemente que vayas al <color=#FFB400>Faro</color> que se asienta al borde del mar y enciendas su luz.",
  ui_story_5012_50121001_13_dialog_content = "En estos tiempos oscuros, la gente ha rezado anhelando su luz y su liberación del mal.",
  ui_story_5012_50121001_14_dialog_content = "Muy bien.",
  ui_story_5012_50121001_15_dialog_content = "Entiendo.",
  ui_story_5012_50121001_16_dialog_content = "¡Espera!",
  ui_story_5012_50121001_17_dialog_content = "¡Déjame ir contigo! ¡Luchamos juntos todo este tiempo, después de todo!",
  ui_story_5012_50121001_18_dialog_content = "Aunque eres mucho más fuerte ahora que antes, yo ...",
  ui_story_5012_50121001_19_dialog_content = "¡Sé que todavía puedo ayudar de alguna manera!",
  ui_story_5012_50121001_20_dialog_content = "...",
  ui_story_5012_50121001_21_dialog_content = "¿Eh?",
  ui_story_5012_50121001_22_dialog_content = "¿P-por qué me está ignorando ...?",
  ui_story_5012_50121001_23_dialog_content = "¡Esperar! ¡Shaya!",
  ui_story_5012_50121001_24_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5012_50121001_25_dialog_content = "Suficiente.",
  ui_story_5012_50121001_26_dialog_content = "Desde entonces ha perdido ese nombre. Nadie responderá ahora.",
  ui_story_5012_50121001_27_dialog_content = "La única persona que queda es la reina. Bethlehem.",
  ui_story_5012_50121001_28_dialog_content = "¿Pero por qué?",
  ui_story_5012_50121001_29_dialog_content = "Ella solo tiene un nombre diferente ahora, ¿verdad? ¡Sigue siendo la misma persona que antes!",
  ui_story_5012_50121001_30_dialog_content = "Sí, pero ahora ... Ella es la reina de todo Northland.",
  ui_story_5012_50121001_31_dialog_content = "Y como tal, ella va ahora a pelear una batalla que es solo de ella.",
  ui_story_5012_50121001_32_dialog_content = "\"¿Una batalla que es solo de ella\"? ¿Que se supone que significa eso?",
  ui_story_5012_50121001_33_dialog_content = "Es su responsabilidad, su carga de soportar como heredera de la Chispa.",
  ui_story_5012_50121001_34_dialog_content = "Aquellos sin poder no están autorizados ni son dignos de unirse a ella.",
  ui_story_5012_50121001_35_dialog_content = "Porque ella ha evitado su sentido de sí misma y lucha no en nombre de una sola persona, sino en nombre de todo el Norte de la Tierra.",
  ui_story_5012_50121001_36_dialog_content = "Eso ... Todavía no tiene sentido para mí.",
  ui_story_5012_50121001_37_dialog_content = "Eso es de esperar.",
  ui_story_5012_50121001_38_dialog_content = "Sólo sé que todo está procediendo según lo planeado.",
  ui_story_5012_50121001_39_dialog_content = "Es responsabilidad de la reina liberar a Northland del peligro y librar al reino de todas y cada una de las amenazas.",
  ui_story_5012_50121001_40_dialog_content = "La responsabilidad de la reina ...",
  ui_story_5012_50121001_41_dialog_content = "Así es.",
  ui_story_5012_50121001_42_dialog_content = "...",
  ui_story_5012_50121001_43_dialog_content = "¡No! ¡No puedo aceptar eso!",
  ui_story_5012_50121001_44_dialog_content = "¿Mmm?",
  ui_story_5012_50121001_45_dialog_content = "¡Es como darme una historia para leer!",
  ui_story_5012_50121001_46_dialog_content = "Me lo diste y me pediste que lo leyera, así que tengo ...",
  ui_story_5012_50121001_47_dialog_content = "¡¿Cómo pudiste decirme que pare antes de saber cómo termina todo ?!",
  ui_story_5012_50121001_48_dialog_content = "¡Esperar! ¡No debes irte!",
  ui_story_5012_50121001_49_dialog_content = "¡Shaya! ¿Dónde están...?",
  ui_story_5012_50121001_50_dialog_content = "¡Graaagh!",
  ui_story_5012_50121001_51_dialog_content = "¡Graah! ¡¡Graaah !!",
  ui_story_5012_50121001_52_dialog_content = "¡¿E-Eclipsites?!",
  ui_story_5012_50121001_53_dialog_content = "Como dije antes ... Esto es una batalla.",
  ui_story_5012_50121002_1_dialog_content = "No tenía idea de que fuera tan malo ...",
  ui_story_5012_50121002_2_dialog_content = "Y ahora lo haces.",
  ui_story_5012_50121002_3_dialog_content = "Entrar en este campo de batalla sería un suicidio para cualquier persona común.",
  ui_story_5012_50121002_4_dialog_content = "Pero la reina ya nos ha dejado muy atrás. No tenemos forma de alcanzarla ahora.",
  ui_story_5012_50121002_5_dialog_content = "...",
  ui_story_5012_50121002_6_dialog_content = "sigo sin entender, Novio.",
  ui_story_5012_50121002_7_dialog_content = "¿Quién es realmente la reina ahora?",
  ui_story_5012_50121002_8_dialog_content = "¿Es Shaya, quien acaba de tomar el trono... o Reina? Bethlehem, ¿quién nos dio la bienvenida a Northland antes?",
  ui_story_5012_50121002_9_dialog_content = "¿Estás preguntando si nuestra reina es la que está en este recuerdo o la reina en el mundo real?",
  ui_story_5012_50121002_10_dialog_content = "S-Sí ...",
  ui_story_5012_50121002_11_dialog_content = "Quiero decir, después de heredar el Chispa, es como si instantáneamente se convirtiera en una persona completamente diferente ...",
  ui_story_5012_50121002_12_dialog_content = "Como estamos en una visión del pasado, ella acaba de ascender al trono dentro de este espacio.",
  ui_story_5012_50121002_13_dialog_content = "Pero es innegable que la conciencia de la reina se ha despertado desde lo más profundo de su línea de sangre.",
  ui_story_5012_50121002_14_dialog_content = "Entonces ... ¿Cómo debo dirigirme a ella?",
  ui_story_5012_50121002_15_dialog_content = "En esta visión, Shaya es como una niña pequeña... Pero en el mundo real, Queen Bethlehem habla y actúa de manera completamente diferente. Siento que debería dirigirme a ella como a mi mayor...",
  ui_story_5012_50121002_16_dialog_content = "No creo que esto merezca tanto pensamiento como usted lo está pensando.",
  ui_story_5012_50121002_17_dialog_content = "Independientemente del tiempo o el espacio, siempre que haya completado el ritual de la ascensión, ella es la Reina. Bethlehem.",
  ui_story_5012_50121002_18_dialog_content = "El paso del tiempo no ha cambiado quién es ella en el fondo. La reina Bethlehem del pasado no es diferente a la Reina Bethlehem de la actualidad.",
  ui_story_5012_50121002_19_dialog_content = "Y-ya veo ...",
  ui_story_5012_50121002_20_dialog_content = "Así es.",
  ui_story_5012_50121002_21_dialog_content = "La reina es tan inmutable como la propia Northland.",
  ui_story_5012_50121002_22_dialog_content = "Incluso si la conciencia de la reina se ha despertado, sus deberes con nuestro reino siguen siendo los mismos.",
  ui_story_5012_50121002_23_dialog_content = "Estás hablando de volver a encender la baliza del faro, ¿verdad?",
  ui_story_5012_50121002_24_dialog_content = "¿Tiene más sentido realizar este acto?",
  ui_story_5012_50121002_25_dialog_content = "Intentaré explicártelo lo mejor que pueda.",
  ui_story_5012_50121002_26_dialog_content = "¡Muy bien, soy todo oídos!",
  ui_story_5012_50121002_27_dialog_content = "Durante generaciones, Northland ha recibido una gran y poderosa bendición.",
  ui_story_5012_50121002_28_dialog_content = "Esta bendición es conocida por usted y el resto del mundo como \"Luminatics\".",
  ui_story_5012_50121002_29_dialog_content = "Envuelve la totalidad de nuestro reino de frontera a frontera, evitando cualquier intrusión Eclipsite.",
  ui_story_5012_50121002_30_dialog_content = "Hemos empezado a llamar a este poder el \"<color=#FFB400>Santuario</color>\".",
  ui_story_5012_50121002_31_dialog_content = "Comprendo.",
  ui_story_5012_50121002_32_dialog_content = "Naturalmente, Luminatics como este requieren una gran cantidad de poder para mantenerse.",
  ui_story_5012_50121002_33_dialog_content = "En cuanto a la fuente de ese poder ... estoy seguro de que ya lo ha adivinado.",
  ui_story_5012_50121002_34_dialog_content = "El poder de la chispa ...",
  ui_story_5012_50121002_35_dialog_content = "Así es.",
  ui_story_5012_50121002_36_dialog_content = "También es por esta razón que Northland siempre debe tener un monarca que lo gobierne.",
  ui_story_5012_50121002_37_dialog_content = "El Faro es el núcleo del \"Santuario\".",
  ui_story_5012_50121002_38_dialog_content = "Mientras permanezca encendido, las tierras dentro de nuestras fronteras estarán a salvo de daños.",
  ui_story_5012_50121002_39_dialog_content = "Pero como puede ver actualmente, todo está oscuro en dirección al Faro.",
  ui_story_5012_50121002_40_dialog_content = "Con el poder que ha heredado, la reina debe viajar al Faro y reactivar el Santuario.",
  ui_story_5012_50121002_41_dialog_content = "Solo cuando se vuelva a encender el faro, escaparemos de esta crisis y volveremos a tiempos de paz una vez más.",
  ui_story_5012_50121002_42_dialog_content = "Pero esa es una responsabilidad tan grande ... ¿Estará ella realmente bien sola?",
  ui_story_5012_50121002_43_dialog_content = "Hay tantos enemigos entre ella y el faro ... Sin mencionar el duro entorno de Northland ...",
  ui_story_5012_50121002_44_dialog_content = "Y antes de irse, estaba claramente ...",
  ui_story_5012_50121002_45_dialog_content = "No hay otra manera.",
  ui_story_5012_50121002_46_dialog_content = "Como reina de Northland y heredera de Chispa, este es su deber y solo suyo.",
  ui_story_5012_50121002_47_dialog_content = "Nadie puede ayudarla ahora.",
  ui_story_5012_50121002_48_dialog_content = "... ¿Es eso lo que usted y el resto de la gente de Northland creen?",
  ui_story_5012_50121002_49_dialog_content = "Todavía no puedo aceptarlo en absoluto, pero ... haré todo lo posible para entenderlo.",
  ui_story_5012_50121101_1_dialog_content = "¡Ella se está acercando!",
  ui_story_5012_50121101_2_dialog_content = "Puedo verla allí ...",
  ui_story_5012_50121101_3_dialog_content = "Increíble...",
  ui_story_5012_50121101_4_dialog_content = "<size=45>¡Graaah!</size>",
  ui_story_5012_50121101_5_dialog_content = "¡Cuidado!",
  ui_story_5012_50121101_6_dialog_content = "Manténgase alerta; ¡Corres mucho más peligro aquí que ella allá!",
  ui_story_5012_50121101_7_dialog_content = "Lo-lo siento...",
  ui_story_5012_50121101_8_dialog_content = "Tienes razón, debería concentrarme en lo que me rodea.",
  ui_story_5012_50121101_9_dialog_content = "¡La reina está más adelante! ¡Podemos localizarla en poco tiempo si lo intentamos!",
  ui_story_5012_50121101_10_dialog_content = "...",
  ui_story_5012_50121101_11_dialog_content = "No puedo desviarme de mi postura.",
  ui_story_5012_50121101_12_dialog_content = "No debemos acercarnos más.",
  ui_story_5012_50121101_13_dialog_content = "¿Pero por qué?",
  ui_story_5012_50121101_14_dialog_content = "Todavía le queda un largo camino por recorrer antes de llegar al faro ... ¿De verdad estás de acuerdo con verla luchar por su cuenta?",
  ui_story_5012_50121101_15_dialog_content = "Sí.",
  ui_story_5012_50121101_16_dialog_content = "Tú ...",
  ui_story_5012_50121101_17_dialog_content = "Pensé que te preocupabas más por la reina que eso ...",
  ui_story_5012_50121101_18_dialog_content = "Pero parece que ahora eres un súbdito leal suyo, ¿no es así?",
  ui_story_5012_50121101_19_dialog_content = "... Correcto.",
  ui_story_5012_50121101_20_dialog_content = "¡Como el infierno! ¡Sé que no es así como te sientes en absoluto!",
  ui_story_5012_50121101_21_dialog_content = "Soy celestita, ¡recuerda! ¡Puedo decir exactamente cómo se sienten otras personas!",
  ui_story_5012_50121101_22_dialog_content = "¡No me engañes!",
  ui_story_5012_50121101_23_dialog_content = "Mis pensamientos y sentimientos ya no importan.",
  ui_story_5012_50121101_24_dialog_content = "Estas son nuestras tradiciones, que han protegido a Northland durante milenios.",
  ui_story_5012_50121101_25_dialog_content = "¿De qué tradiciones estás hablando ahora?",
  ui_story_5012_50121101_26_dialog_content = "Lo viste con tus propios ojos: para ascender al trono, el sucesor debe abandonar su sentido de sí mismo.",
  ui_story_5012_50121101_27_dialog_content = "Sí, vi eso por mí mismo ...",
  ui_story_5012_50121101_28_dialog_content = "Entregó las cosas que más amaba, e incluso su propio nombre.",
  ui_story_5012_50121101_29_dialog_content = "Pero eso todavía no es suficiente.",
  ui_story_5012_50121101_30_dialog_content = "Porque también debe renunciar a aquellos a quienes llamó \"amigos\" en el pasado.",
  ui_story_5012_50121101_31_dialog_content = "¿Incluso sus amigos ...?",
  ui_story_5012_50121101_32_dialog_content = "Pero recuerdo que dijiste que no tenía ningún amigo de su edad, sólo...",
  ui_story_5012_50121101_33_dialog_content = "Lo que estás experimentando ahora mismo es una visión del pasado, nada más.",
  ui_story_5012_50121101_34_dialog_content = "En realidad, fui yo quien la acompañó hasta el final de este camino.",
  ui_story_5012_50121101_35_dialog_content = "Desde Lago Espejo, caminamos hasta el Palacio de Invierno ... Y ella se aferró a mi ropa todo el tiempo, como cuando era una niña pequeña.",
  ui_story_5012_50121101_36_dialog_content = "Habló más de lo habitual, ya que estaba ansiosa por decir todo lo que sentía que debía decirse antes del final.",
  ui_story_5012_50121101_37_dialog_content = "Cuando llegamos al Palacio de Invierno, su agarre se aflojó.",
  ui_story_5012_50121101_38_dialog_content = "Tuve que arrodillarme para colocar la corona de todo nuestro reino en su cabeza.",
  ui_story_5012_50121101_39_dialog_content = "Ella era tan alta ... La reina más joven a la que había servido en mis años.",
  ui_story_5012_50121101_40_dialog_content = "La vi parpadear dos veces antes de que parte de la luz abandonara sus ojos, para ser reemplazada por una calma tan quieta y profunda como las aguas del Lago Espejo.",
  ui_story_5012_50121101_41_dialog_content = "Levantó la cabeza hacia mí, esperando que la nombrara Reina. Bethlehem, gobernante de Northland.",
  ui_story_5012_50121101_42_dialog_content = "A partir de ese momento, los lazos de amistad entre nosotros se rompieron para siempre ...",
  ui_story_5012_50121101_43_dialog_content = "Todo lo que queda es el vínculo entre gobernante y súbdito.",
  ui_story_5012_50121101_44_dialog_content = "Pero cómo ... ¿Cómo pudiste hacerlo ...?",
  ui_story_5012_50121101_45_dialog_content = "Para criarla como si fuera tuya todo ese tiempo, y luego tirarlo todo en un instante ...",
  ui_story_5012_50121101_46_dialog_content = "No creo que pueda hacerlo ... Eso no es algo que pueda hacer en esta vida o en cualquier otra vida ...",
  ui_story_5012_50121101_47_dialog_content = "Y eso es perfectamente normal.",
  ui_story_5012_50121101_48_dialog_content = "Afortunadamente, mi esperanza de vida se extiende mucho más allá de la de cualquier otro mortal.",
  ui_story_5012_50121101_49_dialog_content = "He criado muchos reyes y reinas en mi tiempo, y he tenido amplias oportunidades de acostumbrarme a estas despedidas.",
  ui_story_5012_50121101_50_dialog_content = "¿Fue así ... con cada rey y reina que criaste?",
  ui_story_5012_50121101_51_dialog_content = "Era.",
  ui_story_5012_50121101_52_dialog_content = "Créame, no me gusta ... Pero hace tiempo que me he acostumbrado.",
  ui_story_5012_50121101_53_dialog_content = "Por el bien de Northland ... ¿Verdad?",
  ui_story_5012_50121101_54_dialog_content = "Naturalmente.",
  ui_story_5012_50121101_55_dialog_content = "Sin un gobernante que se siente en el trono de Northland, nuestra tierra no conocerá ni paz ni prosperidad.",
  ui_story_5012_50121101_56_dialog_content = "...",
  ui_story_5012_50121101_57_dialog_content = "Eres ... Aún no puedes aceptarlo, ¿no?",
  ui_story_5012_50121101_58_dialog_content = "Puedo entenderlo si lo miro desde la perspectiva de todo Northland ...",
  ui_story_5012_50121101_59_dialog_content = "El precio de un poder lo suficientemente grande como para proteger a todo un reino ... Es una decisión difícil, pero clara.",
  ui_story_5012_50121101_60_dialog_content = "Es solo ... Trágico, eso es todo.",
  ui_story_5012_50121101_61_dialog_content = "La forma en que están escritos los cuentos de hadas de Northland es realmente trágica.",
  ui_story_5012_50121101_62_dialog_content = "Le pido disculpas, forastero, si las historias de nuestra tierra no son de su agrado.",
  ui_story_5012_50121101_63_dialog_content = "¡No es eso! Es solo ...",
  ui_story_5012_50121101_64_dialog_content = "Siento que falta algo.",
  ui_story_5012_50121101_65_dialog_content = "¿Algo falta?",
  ui_story_5012_50121101_66_dialog_content = "¡Eso es correcto! ¿Qué tal esto?",
  ui_story_5012_50121101_67_dialog_content = "Todo esto es solo una visión del pasado, ¿verdad?",
  ui_story_5012_50121101_68_dialog_content = "Correcto.",
  ui_story_5012_50121101_69_dialog_content = "Entonces, ¿cuál es el punto de apegarse a las tradiciones aquí?",
  ui_story_5012_50121101_70_dialog_content = "Ya que tienes que mantener las apariencias y seguir las costumbres de tu reino en el mundo real ...",
  ui_story_5012_50121101_71_dialog_content = "¿Por qué no te das la oportunidad de expresar tus verdaderos sentimientos aquí?",
  ui_story_5012_50121101_72_dialog_content = "... De lo que hablas es puro sofisma. Por favor, absténgase de hacer tales argumentos ...",
  ui_story_5012_50121101_73_dialog_content = "¡Está bien, está bien! ¡No diré una palabra más!",
  ui_story_5012_50121101_74_dialog_content = "Además, ¡tus verdaderos sentimientos ya me concuerdan!",
  ui_story_5012_50121101_75_dialog_content = "<size=45>¡Vamos! ¡Vamos a luchar al lado de la reina!</size>",
  ui_story_5012_50121201_1_dialog_content = "<size=45>¡Su Majestad!</size>",
  ui_story_5012_50121201_2_dialog_content = "*Pantalón, pantalón...*",
  ui_story_5012_50121201_3_dialog_content = "Finalmente ... nos pusimos al día ...",
  ui_story_5012_50121201_4_dialog_content = "...",
  ui_story_5012_50121201_5_dialog_content = "Novio Debe haberte explicado las cosas, ¿no?",
  ui_story_5012_50121201_6_dialog_content = "Esta es mi batalla y solo mía.",
  ui_story_5012_50121201_7_dialog_content = "Tus acciones e intenciones son completamente inútiles.",
  ui_story_5012_50121201_8_dialog_content = "¿Por qué piensas eso?",
  ui_story_5012_50121201_9_dialog_content = "¡Estamos luchando contra los Eclipsites, después de todo! ¡Tengo razones más que suficientes para hacer eso!",
  ui_story_5012_50121201_10_dialog_content = "¿Cómo?",
  ui_story_5012_50121201_11_dialog_content = "Como ... Bueno, todo el mundo tiene una razón para luchar contra los Eclipsites, ¿verdad?",
  ui_story_5012_50121201_12_dialog_content = "La mía es porque destruyeron mi casa y masacraron a mi gente hace muchos años ...",
  ui_story_5012_50121201_13_dialog_content = "¿Entonces tu razón para pelear es la venganza?",
  ui_story_5012_50121201_14_dialog_content = "S-Sí ...",
  ui_story_5012_50121201_15_dialog_content = "Supongo que no lo he pensado tanto como debería ...",
  ui_story_5012_50121201_16_dialog_content = "No es del todo por venganza, creo ...",
  ui_story_5012_50121201_17_dialog_content = "Pero es la razón por la que ha elegido, de todos modos.",
  ui_story_5012_50121201_18_dialog_content = "Incluso si pudieras retroceder en el tiempo hasta la destrucción de Eraveil, no hay forma de que lo detengas.",
  ui_story_5012_50121201_19_dialog_content = "Esto es dolorosamente claro para ti, ¿no es así?",
  ui_story_5012_50121201_20_dialog_content = "...",
  ui_story_5012_50121201_21_dialog_content = "La venganza no es motivo de lucha; es un fuego que te consumirá hasta que no quede nada.",
  ui_story_5012_50121201_22_dialog_content = "Si realmente tiene la intención de poner un pie en el campo de batalla, debe encontrar algo que desee proteger.",
  ui_story_5012_50121201_23_dialog_content = "¿Algo que proteger ...?",
  ui_story_5012_50121201_24_dialog_content = "Su Majestad ... ¿Cómo decidió que quería proteger todo Northland?",
  ui_story_5012_50121201_25_dialog_content = "Nací y crecí en Northland.",
  ui_story_5012_50121201_26_dialog_content = "Ésa es razón suficiente.",
  ui_story_5012_50121201_27_dialog_content = "Pero ... ¿Realmente vale la pena sacrificar todo lo que amas?",
  ui_story_5012_50121201_28_dialog_content = "La protección es responsabilidad muy pesada de llevar.",
  ui_story_5012_50121201_29_dialog_content = "A menos que abandone todo lo que he sido, nunca seré digno de llevar esa responsabilidad sobre mis hombros.",
  ui_story_5012_50121201_30_dialog_content = "¿Pero por qué?",
  ui_story_5012_50121201_31_dialog_content = "Porque sólo un inmenso poder es capaz de proteger a toda Northland.",
  ui_story_5012_50121201_32_dialog_content = "Pero el poder... Tiene una tendencia a corromper a los que lo ejercen, y a hacer que estén sedientos de más.",
  ui_story_5012_50121201_33_dialog_content = "Demasiadas veces en nuestra historia hemos visto a la gente desviarse por su búsqueda de mayor poder.",
  ui_story_5012_50121201_34_dialog_content = "Entiendo...",
  ui_story_5012_50121201_35_dialog_content = "Por ello, el abandono del sentido de sí mismo es un prerrequisito indispensable para cualquier sucesor al trono.",
  ui_story_5012_50121201_36_dialog_content = "Sólo así se puede frenar la corrupción del deseo.",
  ui_story_5012_50121201_37_dialog_content = "El sucesor al trono debe ser puesto a prueba por el poder de los gobernantes de Northland. Sólo entonces concederá al reino su protección.",
  ui_story_5012_50121201_38_dialog_content = "...Creo que entiendo un poco más las cosas. Realmente lleva el peso de un reino sobre sus hombros, Su Majestad.",
  ui_story_5012_50121201_39_dialog_content = "Pero todavía no puedo aceptar este tipo de sentimientos.",
  ui_story_5012_50121201_40_dialog_content = "Tal vez sea porque no crecí en mi tierra natal o entre otras personas como yo...",
  ui_story_5012_50121201_41_dialog_content = "Pero sacrificar todo lo que conoces y amas para proteger un pedazo de tierra parece un precio muy alto, si me preguntas...",
  ui_story_5012_50121201_42_dialog_content = "No hay necesidad de que te impongas una carga como esta.",
  ui_story_5012_50121201_43_dialog_content = "Pero lo que sí quiero proteger... ¡Es otra cosa!",
  ui_story_5012_50121201_44_dialog_content = "He ido a todo tipo de lugares y he conocido a todo tipo de gente desde que dejé Eraveil...",
  ui_story_5012_50121201_45_dialog_content = "Desde la más amarga de las batallas hasta el más tranquilo de los días normales, aprecio todo lo que he vivido con ellos.",
  ui_story_5012_50121201_46_dialog_content = "Para mí, esas experiencias son las cosas más preciosas y hermosas de la vida.",
  ui_story_5012_50121201_47_dialog_content = "Y esas preciosas y hermosas experiencias... ¡Son lo que quiero proteger!",
  ui_story_5012_50121201_48_dialog_content = "Lo que buscas proteger es... Mucho más complicado que Northland.",
  ui_story_5012_50121201_49_dialog_content = "¿Pero tienes el poder para hacerlo?",
  ui_story_5012_50121201_50_dialog_content = "Yo... No lo creo...",
  ui_story_5012_50121201_51_dialog_content = "Pero lo que puedo hacer... ¡Es juntar el poder de todos!",
  ui_story_5012_50121201_52_dialog_content = "Puede que no seamos lo suficientemente fuertes ahora, pero algún día...\n¡Algún día seremos lo suficientemente fuertes para cambiar las mareas del destino!",
  ui_story_5012_50121201_53_dialog_content = "¿En serio?",
  ui_story_5012_50121201_54_dialog_content = "Me parece que son las reflexiones de un niño ingenuo y tonto.",
  ui_story_5012_50121201_55_dialog_content = "Con esa mentalidad nunca podrás proteger nada.",
  ui_story_5012_50121201_56_dialog_content = "Yo...",
  ui_story_5012_50121201_57_dialog_content = "Tratar de proteger demasiadas cosas sólo resultará en tu fracaso para proteger nada en absoluto.",
  ui_story_5012_50121201_58_dialog_content = "Dime, ¿por qué elegiste luchar desde el Palacio de Invierno hasta aquí?",
  ui_story_5012_50121201_59_dialog_content = "...",
  ui_story_5012_50121201_60_dialog_content = "para ti reina Bethlehem.",
  ui_story_5012_50121201_61_dialog_content = "¿Para mí?",
  ui_story_5012_50121201_62_dialog_content = "Aunque sólo sea un espejismo, he experimentado todas esas cosas con Shaya igualmente.",
  ui_story_5012_50121201_63_dialog_content = "Si me preguntas, esas experiencias son tan valiosas como cualquier otra cosa.",
  ui_story_5012_50121201_64_dialog_content = "No quiero ver cómo lo tira todo por la borda... Esas cosas que creo que son preciosas...",
  ui_story_5012_50121201_65_dialog_content = "Por eso luché hasta aquí... ¡Para proteger lo que creo que debe ser protegido!",
  ui_story_5012_50121201_66_dialog_content = "Tu deber es sólo volver a encender el faro del Faro, ¿verdad? ¡Eso significa que puedes dejarnos el resto a nosotros!",
  ui_story_5012_50121201_67_dialog_content = "Yo y Novio, ¡también!",
  ui_story_5012_50121201_68_dialog_content = "...",
  ui_story_5012_50121201_69_dialog_content = "(Su Majestad...)",
  ui_story_5012_50121201_70_dialog_content = "Prepararse, Novio! ¡Los eclipses están cada vez más cerca!",
  ui_story_5012_50121201_71_dialog_content = "Si el trabajo de la reina es proteger a toda Northland...\n¡Entonces nuestro trabajo es proteger a la reina!",
  ui_story_5012_50121202_1_dialog_content = "¿Estamos... En el Faro ya...?",
  ui_story_5012_50121202_2_dialog_content = "¿Estás bien?",
  ui_story_5012_50121202_3_dialog_content = "Sí, sólo un poco cansado.",
  ui_story_5012_50121202_4_dialog_content = "¿Quieres que te cargue?",
  ui_story_5012_50121202_5_dialog_content = "Creo que estaré bien, gracias...",
  ui_story_5012_50121202_6_dialog_content = "¡Cuidado atrás de ti!",
  ui_story_5012_50121202_7_dialog_content = "¡¡Graaaah!!",
  ui_story_5012_50121202_8_dialog_content = "Mi agradecimiento.",
  ui_story_5012_50121202_9_dialog_content = "Me lo puedes agradecer después!",
  ui_story_5012_50121202_10_dialog_content = "Una vez que la reina vuelva a encender el Faro, todo esto habrá terminado... ¿Verdad?",
  ui_story_5012_50121202_11_dialog_content = "Correcto.",
  ui_story_5012_50121202_12_dialog_content = "¿Qué aspecto tiene cuando se reenciende la luz?",
  ui_story_5012_50121202_13_dialog_content = "¿Cómo es...? Por qué, es una vista más hermosa que el cielo nocturno lleno de estrellas.",
  ui_story_5012_50121202_14_dialog_content = "¿Es así? ¡Entonces no puedo esperar a verlo!",
  ui_story_5012_50121202_15_dialog_content = "Puede ir a reavivar el faro ahora, Su Majestad. Nosotros nos encargaremos de las cosas aquí.",
  ui_story_5012_50121202_16_dialog_content = "¡Sí! ¡Deja el resto de estos Eclipsites aquí para nosotros!",
  ui_story_5012_50121202_17_dialog_content = "...",
  ui_story_5012_50121202_18_dialog_content = "(Su resolución...)",
  ui_story_5012_50121202_19_dialog_content = "(Quiero que me lo demuestres.)",
  ui_story_5012_50121301_1_dialog_content = "¿De nuevo en el Faro, Srta. Shaya?",
  ui_story_5012_50121301_2_dialog_content = "Yo.. No quería seguir escuchando lo que esos adultos tenían que decir.",
  ui_story_5012_50121301_3_dialog_content = "*Asiente* Entiendo.",
  ui_story_5012_50121301_4_dialog_content = "Tenga la seguridad de que ya les he pedido que se vayan.",
  ui_story_5012_50121301_5_dialog_content = "Te... ¿Puedo quedarme aquí un poco más?",
  ui_story_5012_50121301_6_dialog_content = "Puedes quedarte hasta que tengas hambre, si lo deseas. La cena es una parte importante de tu día, después de todo.",
  ui_story_5012_50121301_7_dialog_content = "No tengo hambre... Sólo quiero quedarme aquí para siempre...",
  ui_story_5012_50121301_8_dialog_content = "Aquí no hay adultos malos... Solo tú y yo, Novio.",
  ui_story_5012_50121301_9_dialog_content = "Si eso es lo que desea, Srta. Shaya.",
  ui_story_5012_50121301_10_dialog_content = "Puedes venir al Faro cuando desees escapar de tus problemas.",
  ui_story_5012_50121301_11_dialog_content = "Bien...",
  ui_story_5012_50121301_12_dialog_content = "Pero recuerda que un día...",
  ui_story_5012_50121301_13_dialog_content = "Te corresponderá a ti volver a encender el faro del Faro.",
  ui_story_5012_50121301_14_dialog_content = "<size=50>¡Graaaah!</size>",
  ui_story_5012_50121301_15_dialog_content = "A su derecha, Novio!",
  ui_story_5012_50121301_16_dialog_content = "¡Izquierda! ¡De nuevo!",
  ui_story_5012_50121301_17_dialog_content = "*Jadeando* El siguiente es...",
  ui_story_5012_50121301_18_dialog_content = "!",
  ui_story_5012_50121301_19_dialog_content = "¡¡Graaoooooohhh!!",
  ui_story_5012_50121301_20_dialog_content = "¡PlayerName!",
  ui_story_5012_50121301_21_dialog_content = "¿Está todo bien?",
  ui_story_5012_50121301_22_dialog_content = "¡Este no es el momento de perder la concentración!",
  ui_story_5012_50121301_23_dialog_content = "No perdí la concentración, yo...",
  ui_story_5012_50121301_24_dialog_content = "No puedo sentirlos más, de repente...",
  ui_story_5012_50121301_25_dialog_content = "¡No puedo sentir ninguno de los Eclipsites alrededor!",
  ui_story_5012_50121301_26_dialog_content = "No sabía que eso pudiera pasar...",
  ui_story_5012_50121301_27_dialog_content = "¿Sabes la causa de esto?",
  ui_story_5012_50121301_28_dialog_content = "Yo no...",
  ui_story_5012_50121301_29_dialog_content = "Aún puedo sentir a Lumina, pero los Eclipsites...",
  ui_story_5012_50121301_30_dialog_content = "Es como si hubieran desaparecido completamente de mi mundo.",
  ui_story_5012_50121301_31_dialog_content = "Rayos... ¿Qué debo hacer ahora...?",
  ui_story_5012_50121301_32_dialog_content = "Si aún puedes sentir a Lumina, entonces eso servirá.",
  ui_story_5012_50121301_33_dialog_content = "Puede que no seas capaz de sentir a los Eclipsites con tus poderes, pero aún tienes dos ojos perfectamente buenos en los que confiar.",
  ui_story_5012_50121301_34_dialog_content = "¡Estás en lo correcto!",
  ui_story_5012_50121301_35_dialog_content = "Yo... ¡Aún puedo seguir luchando!",
  ui_story_5012_50121301_36_dialog_content = "Déjame ver... El siguiente enemigo es...",
  ui_story_5012_50121301_37_dialog_content = "...",
  ui_story_5012_50121301_38_dialog_content = "Ey, Novio? Esa gran masa negra de allí... Eso no es una horda de eclipses, ¿verdad?",
  ui_story_5012_50121301_39_dialog_content = "Ciertamente lo es... ¿O es que te has olvidado de cómo son los Eclipsites después de la lucha que hemos hecho hasta ahora?",
  ui_story_5012_50121301_40_dialog_content = "Pero son demasiados, ¿no crees?",
  ui_story_5012_50121301_41_dialog_content = "¿No te preocupas tú o tu gente cuando ves una enorme multitud de esas cosas rodeándote?",
  ui_story_5012_50121301_42_dialog_content = "En absoluto, porque tenemos...",
  ui_story_5012_50121301_43_dialog_content = "¡Lo sé, lo sé! Tienes a tu reina, ¿verdad?",
  ui_story_5012_50121301_44_dialog_content = "¡Ya lo he oído todo antes!",
  ui_story_5012_50121301_45_dialog_content = "Bueno, es cierto...",
  ui_story_5012_50121301_46_dialog_content = "hizo la reina Bethlehem realmente luchó contra tantos Eclipsites en su camino hacia el Faro... ¡¿Toda ella sola?!",
  ui_story_5012_50121301_47_dialog_content = "En seguida.",
  ui_story_5012_50121301_48_dialog_content = "Pero en aquel entonces... ¡No podía tener más de diez años!",
  ui_story_5012_50121301_49_dialog_content = "Cuando tenía diez... Olvídate de luchar contra un Eclipsite, ni siquiera podía con una Luciérnaga...",
  ui_story_5012_50121301_50_dialog_content = "La edad no es necesariamente proporcional a la fuerza real de una persona.",
  ui_story_5012_50121301_51_dialog_content = "¡¡Eso es fácil de decir para ti!!",
  ui_story_5012_50121301_52_dialog_content = "Graaahh!",
  ui_story_5012_50121301_53_dialog_content = "¿Oíste ese sonido detrás de nosotros?",
  ui_story_5012_50121301_54_dialog_content = "¿Qué sonido?",
  ui_story_5012_50121301_55_dialog_content = "Los pasos de la reina.",
  ui_story_5012_50121301_56_dialog_content = "Ligeros y sutiles... Completamente diferentes a los de un Aurorian.",
  ui_story_5012_50121301_57_dialog_content = "¿Quizás eres capaz de percibirlos porque eres una Celestita?",
  ui_story_5012_50121301_58_dialog_content = "¿Cómo te suenan sus pasos?",
  ui_story_5012_50121301_59_dialog_content = "Está caminando por las escaleras, y el sonido de sus pasos es cada vez más silencioso... Como el sonido de un reloj.",
  ui_story_5012_50121301_60_dialog_content = "Cuando escucho ese sonido, me da la sensación de que la reina está luchando a nuestro lado.",
  ui_story_5012_50121301_61_dialog_content = "Con el sonido de cada paso, ella está un paso más cerca de su destino.",
  ui_story_5012_50121301_62_dialog_content = "Entonces debemos seguir luchando hasta que el sonido de sus pasos se detenga, ¿correcto?",
  ui_story_5012_50121301_63_dialog_content = "Así es. ¿Estás seguro de que podemos aguantar hasta entonces, Novio?",
  ui_story_5012_50121301_64_dialog_content = "Tengan la seguridad, como alguien que ha vivido durante siglos... La persistencia es de mis puntos fuertes.",
  ui_story_5012_50121302_1_dialog_content = "¿Cuántos enemigos quedan?",
  ui_story_5012_50121302_2_dialog_content = "¿Podemos... realmente aguantar...?",
  ui_story_5012_50121302_3_dialog_content = "Por supuesto podemos.",
  ui_story_5012_50121302_4_dialog_content = "Puedo decir que su poder está empezando a disminuir.",
  ui_story_5012_50121302_5_dialog_content = "No pueden quedar muchos Eclipsites.",
  ui_story_5012_50121302_6_dialog_content = "¿Cómo es posible que la reina aún no esté en la cima del Faro?",
  ui_story_5012_50121302_7_dialog_content = "¿Estaba haciendo suficiente ejercicio antes?",
  ui_story_5012_50121302_8_dialog_content = "...",
  ui_story_5012_50121302_9_dialog_content = "Aunque supongo que cuando eres la siguiente en la línea de sucesión al trono, no tienes que hacer mucho por ti misma...",
  ui_story_5012_50121302_10_dialog_content = "¡Cuidado!",
  ui_story_5012_50121302_11_dialog_content = "¿¿¿???",
  ui_story_5012_50121302_12_dialog_content = "¡¿Qué es eso?!",
  ui_story_5012_50121302_12X1_dialog_content = "¡Desapareció, así de fácil!",
  ui_story_5012_50121302_13_dialog_content = "¿Un Eclipsite humanoide?",
  ui_story_5012_50121302_13X1_dialog_content = "Siento que he visto esto en algún lugar antes...",
  ui_story_5012_50121302_13X2_dialog_content = "¡Así es! ¡Fue en ese sueño que tuve sobre la caída de Eraveil!",
  ui_story_5012_50121302_14_dialog_content = "Y-Y...",
  ui_story_5012_50121302_15_dialog_content = "No creo que sea un Eclipsite...",
  ui_story_5012_50121302_16_dialog_content = "¿No es un Eclipsite?",
  ui_story_5012_50121302_17_dialog_content = "Pero su presencia definitivamente no es la de un Aurorian...",
  ui_story_5012_50121302_17X5_dialog_content = "¡Y se fue de nuevo!",
  ui_story_5012_50121302_17X6_dialog_content = "¿Qué está pasando aquí...? ¿A dónde se fue...?",
  ui_story_5012_50121302_17X1_dialog_content = "Tu sueño de la destrucción de Eraveil era una proyección de tu corazón.",
  ui_story_5012_50121302_17X2_dialog_content = "Todo en el sueño estaba relacionado contigo.",
  ui_story_5012_50121302_17X3_dialog_content = "Tus recuerdos, tu odio, tus miedos...",
  ui_story_5012_50121302_17X4_dialog_content = "Piénsalo bien. ¿Qué es exactamente?",
  ui_story_5012_50121302_18_dialog_content = "No puedo sentirlo... Alguna fuerza desconocida me impide acercarme...",
  ui_story_5012_50121302_19_dialog_content = "Confías demasiado en tus poderes.",
  ui_story_5012_50121302_20_dialog_content = "Una vez que tu poder de percepción se reduce al de una persona ordinaria, fallas en producir incluso el más básico de los juicios.",
  ui_story_5012_50121302_21_dialog_content = "¡Ir a la batalla con una mentalidad tan poco entusiasta sólo significará tu perdición tarde o temprano!",
  ui_story_5012_50121302_22_dialog_content = "¡PlayerName!",
  ui_story_5012_50121302_23_dialog_content = "¡No interfieras!",
  ui_story_5012_50121302_24_dialog_content = "Estás al final de tu camino, y es inútil tratar de ocultarlo. Mi fuerza es mucho mayor que la tuya en este momento.",
  ui_story_5012_50121302_25_dialog_content = "(Justo ahora, el que bloquea mis poderes... ¿Era él?)",
  ui_story_5012_50121302_26_dialog_content = "(Si me concentro, aún podría tener una oportunidad de entrar en la conciencia de este tipo...)",
  ui_story_5012_50121302_27_dialog_content = "(Como antes...)",
  ui_story_5012_50121302_28_dialog_content = "Oye, tú mismo lo has dicho: No soy un Eclipsite.",
  ui_story_5012_50121302_29_dialog_content = "La misma estrategia que usaste contra los Eclipsites... ¿Realmente crees que va a funcionar conmigo?",
  ui_story_5012_50121302_30_dialog_content = "(¿Qué diablos es este tipo...?)",
  ui_story_5012_50121302_31_dialog_content = "<size=45>(¿Qué piensas?)</size>",
  ui_story_5012_50121302_32_dialog_content = "<size=45>¿¡¿?!?</size>",
  ui_story_5012_50121302_33_dialog_content = "Espera, mi mente... ¡¿Entró en mi conciencia en su lugar?!",
  ui_story_5012_50121302_34_dialog_content = "¿Cuál es el problema? ¿Molesto porque otro puede hacerlo mejor que tú? No eres tan especial ahora, ¿verdad?",
  ui_story_5012_50121302_35_dialog_content = "Ahora lo entiendo... Tú...",
  ui_story_5012_50121302_36_dialog_content = "Tienes los mismos poderes que yo...",
  ui_story_5012_50121302_37_dialog_content = "Lo que significa que no eres un Aurorian o un Eclipsite...",
  ui_story_5012_50121302_38_dialog_content = "<size=45>¡Eres Celestita!</size>",
  ui_story_5012_50121302_39_dialog_content = "Así que lo descubriste, ¿eh? Eres lento, pero no tanto como pensaba.",
  ui_story_5012_50121302_40_dialog_content = "¿Pero cómo es que también tienes este tipo de poder?",
  ui_story_5012_50121302_41_dialog_content = "Pensé que las Celestitas eran...",
  ui_story_5012_50121302_42_dialog_content = "¿Eran qué? ¿Débiles? ¿Indefensos? ¿Sólo buenos para esconderse detrás de las espaldas de los Aurorian más fuertes, como tú?",
  ui_story_5012_50121302_43_dialog_content = "No... Las Celestitas son mucho más de lo que crees.",
  ui_story_5012_50121302_44_dialog_content = "Pero dime, ¿cómo crees que somos exactamente?",
  ui_story_5012_50121302_45_dialog_content = "Con nuestra capacidad innata de sentir y percibir Lumina, los Aurorian son prácticamente ciegos comparados con nosotros.",
  ui_story_5012_50121302_46_dialog_content = "Lamentablemente, todo tiene un precio, y el precio de nuestra percepción mejorada es nuestra incapacidad para controlar a Lumina.",
  ui_story_5012_50121302_47_dialog_content = "¿Pero no te has preguntado alguna vez? ¿Qué pasaría si tuviéramos el poder de los Aurorian?",
  ui_story_5012_50121302_48_dialog_content = "...",
  ui_story_5012_50121302_49_dialog_content = "¿Y si tuviéramos el poder de los Eclipsites, además de eso?",
  ui_story_5012_50121302_50_dialog_content = "¡Eres demasiado avaro!",
  ui_story_5012_50121302_51_dialog_content = "¿Avaro? No, la búsqueda del poder no puede llamarse \"codicia\".",
  ui_story_5012_50121302_52_dialog_content = "Un niño estudiando en la escuela, o un soldado entrenándose en las formas de combate... Ambos se esfuerzan por conseguir un poder aún mayor.",
  ui_story_5012_50121302_53_dialog_content = "¿Los llamarías también \"codiciosos\"?",
  ui_story_5012_50121302_54_dialog_content = "¡Eso es completamente diferente!",
  ui_story_5012_50121302_55_dialog_content = "¡Y ahí es donde te equivocas! El poder es puro, ¿ves?",
  ui_story_5012_50121302_56_dialog_content = "¡Y las lecciones que nos ofrece son bastante directas!",
  ui_story_5012_50121302_57_dialog_content = "¡Como ahora mismo, por ejemplo! Sin el poder, tú y tu amigo estarían acabados aquí y ahora.",
  ui_story_5012_50121302_58_dialog_content = "Tus luchas hasta este momento, y la determinación que mostraste a la reina... Todo ello perdería su significado.",
  ui_story_5012_50121302_59_dialog_content = "¿Te parece bien?",
  ui_story_5012_50121302_60_dialog_content = "...",
  ui_story_5012_50121302_61_dialog_content = "Pero tienes otra opción.",
  ui_story_5012_50121302_62_dialog_content = "Podría decirte cómo obtener un poder aún mayor.",
  ui_story_5012_50121302_63_dialog_content = "...",
  ui_story_5012_50121302_64_dialog_content = "¿Sientes mi espada presionando contra tu piel?",
  ui_story_5012_50121302_65_dialog_content = "Tienes hasta que atraviese tu cuerpo para darme tu respuesta.",
  ui_story_5012_50121302_66_dialog_content = "Espero sea lo respuesta correcta.",
  ui_story_5012_50121302_67_dialog_content = "Creo que... ¿Te equivocas en algo?",
  ui_story_5012_50121302_68_dialog_content = "¿Y eso sería...?",
  ui_story_5012_50121302_69_dialog_content = "Es cierto que sin poder, perdería ante ti.",
  ui_story_5012_50121302_70_dialog_content = "Pero la cosa es... No tengo miedo al fracaso.",
  ui_story_5012_50121302_71_dialog_content = "¿No le temes al fracaso?",
  ui_story_5012_50121302_72_dialog_content = "Ganar todo el tiempo sólo hace que una persona anhele más y más poder.",
  ui_story_5012_50121302_73_dialog_content = "Pero para mí... Ganar no me aporta nada.",
  ui_story_5012_50121302_74_dialog_content = "¡Mentiras! ¿Qué te quedaría después de perder?",
  ui_story_5012_50121302_75_dialog_content = "Estarías muerto. ¡No tendrías nada!",
  ui_story_5012_50121302_76_dialog_content = "Mientras lo dé todo, aceptaré cualquier resultado.",
  ui_story_5012_50121302_77_dialog_content = "¿\"Aceptar\"...? ¿Podrías realmente pagar el precio del fracaso?",
  ui_story_5012_50121302_78_dialog_content = "La razón por la que estoy constantemente tratando de hacerme más fuerte es para poder hacer eso.",
  ui_story_5012_50121302_79_dialog_content = "Además... no estoy solo.",
  ui_story_5012_50121302_80_dialog_content = "Si fracaso, siempre puedo dejarlo en manos de mis amigos, y de los otros de los que he llegado a depender.",
  ui_story_5012_50121302_81_dialog_content = "Y aún no me han defraudado.",
  ui_story_5012_50121302_82_dialog_content = "Al igual que quiero proteger a mis amigos, ¡ellos también me protegerán siempre!",
  ui_story_5012_50121302_83_dialog_content = "¡Ridículo!",
  ui_story_5012_50121302_84_dialog_content = "¡Nunca pensé que un tonto testarudo como tú atribuyera tu supervivencia a la suerte!",
  ui_story_5012_50121302_85_dialog_content = "No fue sólo suerte.",
  ui_story_5012_50121302_86_dialog_content = "Si eres una Celestita como yo, entonces estoy segura de que puedes escuchar ese sonido desde el interior del Faro, ¿también?",
  ui_story_5012_50121302_87_dialog_content = "...",
  ui_story_5012_50121302_88_dialog_content = "No escucho nada proveniente del Faro.",
  ui_story_5012_50121302_89_dialog_content = "Tienes toda la razón. Ni un solo sonido.",
  ui_story_5012_50121302_90_dialog_content = "Eso significa que los pasos en las escaleras... se han detenido.",
  ui_story_5012_50121302_91_dialog_content = "!",
  ui_story_5012_50121302_92_dialog_content = "La reina ha llegado a la cima del Faro.",
  ui_story_5012_50121302_92X1_dialog_content = "El faro está a punto de encenderse, marcando el restablecimiento del Santuario que vigila Northland.",
  ui_story_5012_50121302_92X2_dialog_content = "Si Novio es correcto, el Santuario destruirá todos los Eclipsites.",
  ui_story_5012_50121302_93_dialog_content = "Se acabó ahora.",
  ui_story_5012_50121302_94_dialog_content = "¡¿Qué?!",
  ui_story_5012_50121302_95_dialog_content = "Yo... No me puedo mover...",
  ui_story_5012_50121302_96_dialog_content = "Parece que este es el límite de ese poder del que estabas tan orgulloso.",
  ui_story_5012_50121302_97_dialog_content = "Frente a un poder aún mayor, las cosas que persigues parecen mucho más insignificantes, ¿no?",
  ui_story_5012_50121302_98_dialog_content = "Ahora es el momento de que enfrentes a tu propio fracaso.",
  ui_story_5012_50121302_99_dialog_content = "Un enemigo tan poderoso, y ahora de repente se ha ido...",
  ui_story_5012_50121302_100_dialog_content = "Esto es Northland, Lord PlayerName. Nadie puede llamarse verdaderamente poderoso ante el poder de nuestra reina.",
  ui_story_5012_50121302_101_dialog_content = "Estás bien, Novio...?",
  ui_story_5012_50121302_102_dialog_content = "Estoy bien.",
  ui_story_5012_50121302_103_dialog_content = "Normalmente, esta lucha no habría sido tan agotadora...",
  ui_story_5012_50121302_104_dialog_content = "Pero después de pasar tantos años al lado de la reina, me he desacostumbrado a la batalla.",
  ui_story_5012_50121302_105_dialog_content = "Genial... Hay más Eclipsites dirigiéndose hacia nosotros desde allí.",
  ui_story_5012_50121302_106_dialog_content = "De verdad...",
  ui_story_5012_50121302_107_dialog_content = "Servirán como una ofrenda adecuada para la coronación de nuestra nueva reina.",
  ui_story_5012_50121302_108_dialog_content = "Eso suena un poco siniestro...",
  ui_story_5012_50121302_109_dialog_content = "Mira allá.",
  ui_story_5012_50121302_110_dialog_content = "El sol finalmente sale.",
  ui_story_5012_50121302_111_dialog_content = "El faro y el amanecer...",
  ui_story_5012_50121302_112_dialog_content = "Dos fuentes de luz, que brillan juntas contra la oscuridad de la noche.",
  ui_story_5012_50121302_113_dialog_content = "En el primer día de la noche polar, sólo vemos la luz del sol durante un breve momento... Y este es ese momento.",
  ui_story_5012_50121302_114_dialog_content = "No vemos el sol durante este tiempo; estos pocos segundos de luz que atraviesan la oscuridad son todo lo que tenemos.",
  ui_story_5012_50121302_115_dialog_content = "Pero los habitantes de Northland siempre mirarán al horizonte con ojos ansiosos por la llegada de este muy breve amanecer.",
  ui_story_5012_50121302_116_dialog_content = "Se quedan despiertos durante la noche más larga del año, todo para dar la bienvenida a este breve momento.",
  ui_story_5012_50121302_117_dialog_content = "Porque después de hoy, cada día verá gradualmente más y más luz del día.",
  ui_story_5012_50121302_118_dialog_content = "La vida despierta en nuestros helados dominios,\nMientras Northland recibe a un nuevo año.",
  ui_story_5012_50121302_119_dialog_content = "Realmente deseo que todos puedan ver esto conmigo, también...",
  ui_story_5012_50121302_120_dialog_content = "Y lo harán... Algún día.",
  ui_story_5012_50121302_121_dialog_content = "La historia aquí ha llegado a su fin, y el espejismo está a punto de desvanecerse.",
  ui_story_5012_50121302_122_dialog_content = "Volvamos a la realidad para disfrutar del Año Nuevo.",
  ui_story_5012_50121401_1_dialog_content = "¡Ah! ¡Allí, mira!",
  ui_story_5012_50121401_2_dialog_content = "Honestamente, ¿cómo pudiste salir corriendo hacia el Lago Espejo así, de repente?",
  ui_story_5012_50121401_3_dialog_content = "¡Si no te das prisa, te perderás la ceremonia de Año Nuevo!",
  ui_story_5012_50121401_4_dialog_content = "Carleen, Vice... Y Lola, también...",
  ui_story_5012_50121401_5_dialog_content = "¿He vuelto al mundo real?",
  ui_story_5012_50121401_6_dialog_content = "¿De qué estás hablando?",
  ui_story_5012_50121401_7_dialog_content = "¿Dónde has estado todo este tiempo?",
  ui_story_5012_50121401_8_dialog_content = "Puede que Northland no tenga Eclipsites, pero eso no es razón para bajar la guardia.",
  ui_story_5012_50121401_9_dialog_content = "¡Ya te has perdido muchas cosas, PlayerName! ¿Por qué has tardado tanto?",
  ui_story_5012_50121401_10_dialog_content = "Acabamos de volver de los mercados, tenían todo tipo de cosas interesantes... ¡Y también comida!",
  ui_story_5012_50121401_11_dialog_content = "¡La comida aquí en Northland es increíble! Tienes que probar las albóndigas fritas con salsa de fresa, ¡son las mejores!",
  ui_story_5012_50121401_12_dialog_content = "¡Cuando nos vayamos, intentaré hacerlas para todos!",
  ui_story_5012_50121401_13_dialog_content = "Parece que realmente me perdí la diversión...",
  ui_story_5012_50121401_14_dialog_content = "¡Deprisa! ¡Tenemos que volver al Palacio de Invierno!",
  ui_story_5012_50121401_15_dialog_content = "Todavía tengo algo para la reina...",
  ui_story_5012_50121401_16_dialog_content = "¿Eh...? ¡Su Majestad!",
  ui_story_5012_50121401_17_dialog_content = "¿Estás disfrutando de las festividades de este año? Lola?",
  ui_story_5012_50121401_18_dialog_content = "Sí. ¡Me he divertido mucho!",
  ui_story_5012_50121401_19_dialog_content = "No esperaba verla aquí, Su Majestad...",
  ui_story_5012_50121401_20_dialog_content = "¿Puedo suponer que usted fue quien convocó a PlayerName aquí?",
  ui_story_5012_50121401_21_dialog_content = "Así es.",
  ui_story_5012_50121401_22_dialog_content = "Pensé que había algo peculiar en la invitación que recibimos antes.",
  ui_story_5012_50121401_23_dialog_content = "Según tengo entendido, Northland rara vez intenta establecer contacto con el mundo exterior, y mucho menos invitar a forasteros a celebrar el año nuevo.",
  ui_story_5012_50121401_24_dialog_content = "¿Tenías asuntos urgentes que discutir con PlayerName?",
  ui_story_5012_50121401_25_dialog_content = "Fuimos a ver el Lago Espejo juntos.",
  ui_story_5012_50121401_26_dialog_content = "Estaba en búsqueda de <color=#FFB400>respuestas</color>, y pude encontrarlas en las aguas del lago.",
  ui_story_5012_50121401_27_dialog_content = "¿En las aguas...?",
  ui_story_5012_50121401_28_dialog_content = "¿También has encontrado las respuestas que buscabas, Celestita?",
  ui_story_5012_50121401_29_dialog_content = "I... Sólo tengo una pregunta.",
  ui_story_5012_50121401_30_dialog_content = "El último enemigo que enfrentamos, esa poderosa Celestita...",
  ui_story_5012_50121401_31_dialog_content = "¿Realmente apareció en el campo de batalla hace todos esos años, también?",
  ui_story_5012_50121401_32_dialog_content = "No lo hizo.",
  ui_story_5012_50121401_33_dialog_content = "Esa clase de enemigo aún no ha aparecido en el mundo.",
  ui_story_5012_50121401_34_dialog_content = "Fue sólo un espejismo, una ilusión vista desde los fragmentos de un futuro roto.",
  ui_story_5012_50121401_35_dialog_content = "El triste final de la Misión de una Celestita por un mayor poder.",
  ui_story_5012_50121401_36_dialog_content = "Ya veo... Ahora lo entiendo.",
  ui_story_5012_50121401_37_dialog_content = "Has demostrado tu determinación.",
  ui_story_5012_50121401_38_dialog_content = "Pero aun así, hoy has perdido ante él.",
  ui_story_5012_50121401_39_dialog_content = "¿Estás descontento por esto?",
  ui_story_5012_50121401_40_dialog_content = "Para nada.",
  ui_story_5012_50121401_41_dialog_content = "Nunca me consideré más débil que él.",
  ui_story_5012_50121401_42_dialog_content = "Estábamos en una situación desesperada, y perder era el único final que podíamos esperar...",
  ui_story_5012_50121401_43_dialog_content = "Pero ahora, mientras tenga a mis amigos a mi lado...",
  ui_story_5012_50121401_44_dialog_content = "¡Él nunca tendría una oportunidad contra mí!",
  ui_story_5012_50121401_45_dialog_content = "Tus respuestas son siempre tan interesantes.",
  ui_story_5012_50121401_46_dialog_content = "¿Te importaría demostrármelo?",
  ui_story_5012_50121401_47_dialog_content = "¿Demostrarme qué es más fuerte: una Celestita sin poder o una Celestita que lo persigue sin cesar?",
  ui_story_5012_50121401_48_dialog_content = "¡Claro que te lo demostraré!",
  ui_story_5012_50121401_49_dialog_content = "Pero cómo exactamente...",
  ui_story_5012_50121401_50_dialog_content = "¿¡¿Ahh?!?",
  ui_story_5012_50121401_51_dialog_content = "¡¿Puedes hacer que esto suceda en el mundo real?!",
  ui_story_5012_50121401_52_dialog_content = "Vengan todos, ha llegado el momento de una pelea de bolas de nieve como nunca se ha visto.",
  ui_story_5012_50121401_53_dialog_content = "¿Una pelea de nieve? ¡Cuenta conmigo!",
  ui_story_5012_50121401_54_dialog_content = "¡Prepárate para comer nieve! ¡Vamos, chicos!",
  ui_story_5012_50121402_1_dialog_content = "Se acabó...",
  ui_story_5012_50121402_2_dialog_content = "*Jadeando* Esto... ¡Esta no es una pelea de nieve ordinaria!",
  ui_story_5012_50121402_3_dialog_content = "Es porque el espejismo de la reina es tan poderoso... Ella realmente está en una liga propia.",
  ui_story_5012_50121402_4_dialog_content = "Durante el corto tiempo que pasé en Northland cuando era niño, la reina utilizó ilusiones similares para crear enemigos contra los que entrenar.",
  ui_story_5012_50121402_5_dialog_content = "Después de tantos años, pensé que al fin me había vuelto mucho más fuerte que antes...",
  ui_story_5012_50121402_6_dialog_content = "Pero después de enfrentarme a la reina una vez más, parece que apenas ha cambiado nada...",
  ui_story_5012_50121402_7_dialog_content = "¡Toma esto! ¡Ja! ¡Eso te enseñará!",
  ui_story_5012_50121402_8_dialog_content = "B-Ten cuidado, Lola!",
  ui_story_5012_50121402_9_dialog_content = "Estoy bien!",
  ui_story_5012_50121402_10_dialog_content = "¡Es sólo un gran muñeco de nieve que la reina armó! ¿Qué miedo puede dar?",
  ui_story_5012_50121402_11_dialog_content = "El peligro no está en tu situación, sino en que cojas un resfriado.",
  ui_story_5012_50121402_12_dialog_content = "Oh, bien...",
  ui_story_5012_50121402_13_dialog_content = "Siempre encuentras cosas de las que preocuparte, Novio.",
  ui_story_5012_50121402_14_dialog_content = "No sería la primera vez que te resfrías por jugar en la nieve sin cuidado.",
  ui_story_5012_50121402_15_dialog_content = "¡Era pequeño entonces! Pero ahora...",
  ui_story_5012_50121402_16_dialog_content = "¡O-Oigan! ¡Miren allá arriba, todos!",
  ui_story_5012_50121402_17_dialog_content = "Es hermoso...",
  ui_story_5012_50121402_18_dialog_content = "¡Wow!",
  ui_story_5012_50121402_19_dialog_content = "No he visto una aurora como esta en años...",
  ui_story_5012_50121402_20_dialog_content = "Northland es realmente un lugar mágico. Aún en la oscuridad de la noche, mi cuerpo está rodeado de una Lumina tan brillante...",
  ui_story_5012_50121402_21_dialog_content = "¿Es Lumina todo lo que tú y las otras Celestitas piensan, PlayerName?",
  ui_story_5012_50121402_22_dialog_content = "Utiliza tus ojos por un segundo, y disfruta de esta hermosa vista...",
  ui_story_5012_50121402_23_dialog_content = "Sí... Es realmente hermoso.",
  ui_story_5012_50121402_24_dialog_content = "La vida en Northland es simple, aunque un poco aburrida.",
  ui_story_5012_50121402_25_dialog_content = "Pero es un lugar que guarda buenos recuerdos para mucha gente.",
  ui_story_5012_50121402_26_dialog_content = "Quizá sea porque la belleza de nuestra tierra es difícil de sustituir por las vistas del mundo exterior.",
  ui_story_5012_50121402_27_dialog_content = "¡Hmph, sólo lo dices para que te escuche, no!",
  ui_story_5012_50121402_28_dialog_content = "Sólo le hablo a los que se preocupan por escuchar.",
  ui_story_5012_50121402_29_dialog_content = "¡Ya lo entiendo! ¿No prometí que volvería al menos una vez al año?",
  ui_story_5012_50121402_30_dialog_content = "Uh... ¡Oh no! ¡Perdí noción del tiempo!",
  ui_story_5012_50121402_31_dialog_content = "¡Rápido! ¡Vuelve al Palacio de Invierno! ¡Aún hay mucho que hacer!",
  ui_story_5012_50121402_32_dialog_content = "¡Hey, ya voy! ¡No tienes que arrastrarme!",
  ui_story_5012_50121402_33_dialog_content = "¡Cómo no vas a estar emocionada! ¡Va a ser genial!",
  ui_story_5012_50121402_34_dialog_content = "Espera. Ropa bonita, mucha comida...\n¡Y todos cantando villancicos frente al Palacio de Invierno!",
  ui_story_5012_50121402_35_dialog_content = "Uh, o-okay... Sólo para un poco, ¿podrías...?",
  ui_story_5012_50121402_36_dialog_content = "¡Eso es! No has aprendido ningún villancico, ¿verdad?",
  ui_story_5012_50121402_37_dialog_content = "¡Tomemos algo de tiempo ahora mismo para aprender algunos!",
  ui_story_5012_50121402_38_dialog_content = "\"El reino del norte, nuestra graciosa madre...♪”",
  ui_story_5012_50121402_39_dialog_content = "Vamos, ¡en conjunto ahora!",
  ui_story_5012_50121402_40_dialog_content = "<anim type=Shake>C-Cómo... Puedes... Correr... Y cantar... Al mismo... ¿Tiempo...?</anim>",
  ui_story_5012_50121402_41_dialog_content = "<anim type=Shake>Corre... O canta... Por favor... ¡Sólo elige uno...!</anim>",
  ui_story_5012_50121402_42_dialog_content = "¡Ah, y una cosa más!",
  ui_story_5012_50121402_43_dialog_content = "<anim type=Shake>P-Por favor... Ten piedad...</anim>",
  ui_story_5012_50121402_44_dialog_content = "¡No olvides preparar también un regalo de Año Nuevo!",
  ui_story_5012_50121501_1_dialog_content = "...",
  ui_story_5012_50121501_2_dialog_content = "¿Su Majestad?",
  ui_story_5012_50121501_3_dialog_content = "¿Estás bien?",
  ui_story_5012_50121501_4_dialog_content = "¿Cuánto tiempo... llevo parado aquí?",
  ui_story_5012_50121501_5_dialog_content = "Diez minutos.",
  ui_story_5012_50121501_6_dialog_content = "Los niños ya han vuelto.",
  ui_story_5012_50121501_7_dialog_content = "Comprendo.",
  ui_story_5012_50121501_8_dialog_content = "May Pregunto... ¿Qué deseabas ver esta vez en las aguas del lago Mirror?",
  ui_story_5012_50121501_9_dialog_content = "El futuro.",
  ui_story_5012_50121501_10_dialog_content = "En los restos de la visión que vi antes, cada futuro que pude percibir contenía a la Celestita.",
  ui_story_5012_50121501_11_dialog_content = "Él es quien puede remodelar el futuro.",
  ui_story_5012_50121501_12_dialog_content = "Pero mi percepción de él siempre ha sido ligeramente errónea.",
  ui_story_5012_50121501_13_dialog_content = "O más bien, sus pensamientos y puntos de vista estaban siempre tan lejos de mi imaginación.",
  ui_story_5012_50121501_14_dialog_content = "Por esta razón, no pude ver los futuros que él había remodelado.",
  ui_story_5012_50121501_15_dialog_content = "¿Pero puedes verlo ahora?",
  ui_story_5012_50121501_16_dialog_content = "En seguida.",
  ui_story_5012_50121501_17_dialog_content = "Tengo curiosidad por saber qué tipo de futuro será.",
  ui_story_5012_50121501_18_dialog_content = "Será un futuro diferente a todo lo que has visto en todos tus muchos años, Novio.",
  ui_story_5012_50121501_19_dialog_content = "Distinto a todo lo que he visto...",
  ui_story_5012_50121501_20_dialog_content = "Pero eso servirá por ahora.",
  ui_story_5012_50121501_21_dialog_content = "Tenemos mucha gente esperándonos en el Palacio de Invierno.",
  ui_story_5012_50121501_22_dialog_content = "puedes volver, Novio.",
  ui_story_5012_50121501_23_dialog_content = "...",
  ui_story_5012_50121501_24_dialog_content = "Como usted ordene, Su Majestad.",
  ui_story_5012_50121501_25_dialog_content = "Campanas, lazos e hilos de seda azul...",
  ui_story_5012_50121501_26_dialog_content = "¿Pero por qué siento que me falta algo? Déjame echar un vistazo a la lista de la compra de nuevo...",
  ui_story_5012_50121501_27_dialog_content = "¡Aaaahh! Rayos, ¡Me olvidé de la estrella del árbol del brillo! ¡También es lo más importante!",
  ui_story_5012_50121501_28_dialog_content = "<size=30>Espera... ¿\"De nuevo\"?</size>",
  ui_story_5012_50121501_29_dialog_content = "Si alguien se entera, Novio no me deja escuchar el final...",
  ui_story_5012_50121501_30_dialog_content = "<size=30>Tengo que pensar en una excusa para volver a los mercados...</size>",
  ui_story_5012_50121501_31_dialog_content = "Lola? ¿Estás buscando algo?",
  ui_story_5012_50121501_32_dialog_content = "<size=45>¡N-No, nada!</size>",
  ui_story_5012_50121501_33_dialog_content = "Yo... ¡Me voy a decorar el árbol brillante ahora!",
  ui_story_5012_50121501_34_dialog_content = "¿Necesitas ayuda con eso? Juraría que te he oído decir...",
  ui_story_5012_50121501_35_dialog_content = "Estábamos a punto de llevar a PlayerName a ver los mercados. ¿Hay algo que necesites que compremos?",
  ui_story_5012_50121501_X33_dialog_content = "Estábamos a punto de echar un vistazo al mercado. ¿Hay algo que quiera que le compremos?",
  ui_story_5012_50121501_X34_dialog_content = "Perdí mi oportunidad la última vez.",
  ui_story_5012_50121501_36_dialog_content = "¡¿En serio?! ¡Oh, son mis héroes!",
  ui_story_5012_50121501_37_dialog_content = "Si no es mucha molestia, ¿pueden ayudarme a comprar una estrella para el árbol brillante mientras están ahí?",
  ui_story_5012_50121501_38_dialog_content = "Claro, pero... ¿Qué aspecto tiene?",
  ui_story_5012_50121501_39_dialog_content = "Déjame pensar... Puedes ir directamente a la segunda tienda de la derecha cuando llegues a los mercados.",
  ui_story_5012_50121501_40_dialog_content = "¡Dígale al dueño que necesita una estrella de árbol navideño extra-extra-grande y él sabrá qué darle!",
  ui_story_5012_50121501_X40_dialog_content = "Muy bien, vamos a salir ahora.",
  ui_story_5012_50121501_X41_dialog_content = "Vice y me quedaré en el Palacio de Invierno para ayudar a decorar. ¿Está bien si vas solo?",
  ui_story_5012_50121501_X42_dialog_content = "¿Eh? ¿No vamos juntos?",
  ui_story_5012_50121501_X43_dialog_content = "¿Qué? ¿No vamos nosotros también?",
  ui_story_5012_50121501_X44_dialog_content = "La última vez, habrías limpiado todo el mercado si no nos hubiéramos puesto firmes.",
  ui_story_5012_50121501_X45_dialog_content = "¡Oye! ¡Sólo quería traer algunos regalos para todos!",
  ui_story_5012_50121501_X46_dialog_content = "Pero realmente había algo que olvidé comprar... PlayerName, ¿podrías recogerlo por mí si tienes la oportunidad?",
  ui_story_5012_50121501_X47_dialog_content = "¿Qué querías comprar?",
  ui_story_5012_50121501_X48_dialog_content = "Tres pequeñas tallas de madera de ciervo de la tercera tienda de la izquierda...",
  ui_story_5012_50121501_X49_dialog_content = "Los de la cuarta tienda de la derecha, un muñeco de nieve pequeño con bufanda roja y dos muñecos de nieve medianos con esos gorritos, y...",
  ui_story_5012_50121501_X50_dialog_content = "¡Un momento! ¿Cómo se supone que voy a recordar todo eso?",
  ui_story_5012_50121501_X51_dialog_content = "¿Cómo puedes recordarlo todo?",
  ui_story_5012_50121501_X52_dialog_content = "Déjame repasarlo, una vez más.",
  ui_story_5012_50121501_X53_dialog_content = "Carleen, sigue adelante y comienza a encender las luces con Lola. Estaré allí en un minuto.",
  ui_story_5012_50121501_X54_dialog_content = "De acuerdo, me adelantaré.",
  ui_story_5012_50121501_X55_dialog_content = "Recuerda pensar antes de comprar.",
  ui_story_5012_50121501_X56_dialog_content = "¡Lo se!",
  ui_story_5012_50121501_X57_dialog_content = "...Déjame buscar un lápiz y un papel.",
  ui_story_5012_50121501_X58_dialog_content = "Olvídalo, no tienes que comprar nada de eso.",
  ui_story_5012_50121501_X59_dialog_content = "¿Eh? ¿Ya no lo quieres?",
  ui_story_5012_50121501_X60_dialog_content = "Un lazo azul... Eso es todo lo que tienes que recordar para comprar.",
  ui_story_5012_50121501_41_dialog_content = "La segunda tienda de la derecha... Este es el lugar, ¿verdad?",
  ui_story_5012_50121501_X61_dialog_content = "Feliz Año Nuevo, señor. ¿En qué puedo ayudarle?",
  ui_story_5012_50121501_X62_dialog_content = "Hola, vengo por esa estrella de madera súper extra grande.",
  ui_story_5012_50121501_X63_dialog_content = "Aquí tiene, está todo listo para usted.",
  ui_story_5012_50121501_X64_dialog_content = "Gracias.",
  ui_story_5012_50121501_X65_dialog_content = "Erm, disculpe mi atrevimiento, pero ¿la señorita Lola no volver este año?",
  ui_story_5012_50121501_X66_dialog_content = "Ha vuelto. Está decorando el árbol de brillo en el Palacio de Invierno ahora mismo.",
  ui_story_5012_50121501_X67_dialog_content = "¡Es un verdadero honor hacer una estrella de madera para el Palacio de Invierno! Por favor, saluda a Lola y Su Majestad para mí!",
  ui_story_5012_50121501_X68_dialog_content = "Seguro.",
  ui_story_5012_50121501_X69_dialog_content = "Erm... ¿Tiene arcos azules en stock?",
  ui_story_5012_50121501_X70_dialog_content = "Sí. ¿Necesita algo más? Lo embolsaré todo junto.",
  ui_story_5012_50121501_42_dialog_content = "¡Hola, señorita! ¿Cómo le ayudo hoy?",
  ui_story_5012_50121501_43_dialog_content = "Estamos buscando... Una estrella \"extra-EXTRA-grande\" para un árbol brillante.",
  ui_story_5012_50121501_44_dialog_content = "Hmm... Entonces tendrá que esperar un poco. Una estrella de este tamaño debe hacerse en el momento, pero le prometo que no tardará mucho.",
  ui_story_5012_50121501_45_dialog_content = "En ese caso, ¿podemos comprar algo en la zona mientras esperamos, y venir a por ella cuando esté lista?",
  ui_story_5012_50121501_46_dialog_content = "¡No es problema!",
  ui_story_5012_50121501_47_dialog_content = "¡Wow, mira allí! ¿Has visto alguna vez arcos tan pequeños?",
  ui_story_5012_50121501_48_dialog_content = "¡Siento que debería traer a casa un montón y ponerlos en las Luciérnagas! ¿No sería lo más bonito, PlayerName?",
  ui_story_5012_50121501_49_dialog_content = "¿Eh? ¿PlayerName? Ugh, ¡¿a dónde se ha escapado esta vez?!",
  ui_story_5012_50121501_50_dialog_content = "D-Disculpe, pero... ¿Qué es esto?",
  ui_story_5012_50121501_51_dialog_content = "Feliz Año Nuevo, amigo mío.",
  ui_story_5012_50121501_52_dialog_content = "Este es un reloj de arena, utilizado para mantener el tiempo. Es un artículo especial, hecho a mano por nuestra familia durante generaciones.",
  ui_story_5012_50121501_53_dialog_content = "\"Aunque el tiempo pase sin fin, el pasado y el futuro siempre estarán en tus manos\". Este es el significado del reloj de arena.",
  ui_story_5012_50121501_54_dialog_content = "Parece que no eres de por aquí, amigo. ¿Por qué no te llevas un reloj de arena a casa como recuerdo, y se lo regalas a un amigo?",
  ui_story_5012_50121501_55_dialog_content = "Claro, me llevaré uno. ¿Podría envolverlo también para mí?",
  ui_story_5012_50121501_56_dialog_content = "¡Aquí estás, PlayerName! ¡Te he buscado por todas partes!",
  ui_story_5012_50121501_57_dialog_content = "¡Mira! No es un mal botín, ¿no crees?",
  ui_story_5012_50121501_58_dialog_content = "...¡¿Realmente tuviste que comprar tantas cosas?!",
  ui_story_5012_50121501_59_dialog_content = "Esta ya es nuestra segunda carrera. Si Vice tuviera más manos o un carro, limpiaría todos los estantes del mercado...",
  ui_story_5012_50121501_60_dialog_content = "¡¿Pero cómo iba a dejar pasar unos adornos tan bonitos?!",
  ui_story_5012_50121501_61_dialog_content = "...La estrella del árbol brillante ya debería estar terminada. Deberíamos volver.",
  ui_story_5012_50121501_62_dialog_content = "Sí, empieza a hacerse tarde... Deberíamos intentar volver al Palacio de Invierno tan pronto como podamos.",
  ui_story_5012_50121501_63_dialog_content = "¿Qué compraste, PlayerName?",
  ui_story_5012_50121501_64_dialog_content = "Oh, un pequeño regalo.",
  ui_story_5012_50121501_X71_dialog_content = "Volví.",
  ui_story_5012_50121501_X72_dialog_content = "Has vuelto, PlayerName.",
  ui_story_5012_50121501_X73_dialog_content = "Ah, en realidad... no tenías que venir a buscarme.",
  ui_story_5012_50121501_X74_dialog_content = "El Palacio de Invierno es muy grande. ¿Seguro que eres capaz de encontrar el salón principal por ti mismo?",
  ui_story_5012_50121501_X75_dialog_content = "...Te lo agradezco.",
  ui_story_5012_50121501_65_dialog_content = "Nuestras disculpas por hacerte esperar, Novio.",
  ui_story_5012_50121501_66_dialog_content = "Ven ahora, Carleen. No hay necesidad de ser tan formal.",
  ui_story_5012_50121501_67_dialog_content = "¿Disfrutaron de los mercados?",
  ui_story_5012_50121501_68_dialog_content = "Sí, vimos todo tipo de decoraciones maravillosas. Creo que volveremos una última vez antes de irnos, y compraremos algunos más para poder decorar a Soroz.",
  ui_story_5012_50121501_69_dialog_content = "¿Soroz?",
  ui_story_5012_50121501_70_dialog_content = "Mi Colossus.",
  ui_story_5012_50121501_71_dialog_content = "Ah... Es un nombre muy bueno.",
  ui_story_5012_50121501_72_dialog_content = "Pero, ¿por qué trajiste una estrella tan grande para un árbol de brillo?",
  ui_story_5012_50121501_73_dialog_content = "Tan grande, de hecho, que sólo se me ocurre un árbol lo bastante grande como para ser coronado por él... A saber, el del Palacio de Invierno.",
  ui_story_5012_50121501_74_dialog_content = "Podría Lola se ha olvidado de comprar uno este año, una vez más...?",
  ui_story_5012_50121501_75_dialog_content = "¡Oye! ¡PlayerName! ¡Por fin has vuelto!",
  ui_story_5012_50121501_76_dialog_content = "¡Aquí, déjame ayudarte a traer todas tus cosas a nuestro almacén! Novio, ¿por qué no tomas PlayerName al gran salón por ahora?",
  ui_story_5012_50121501_X76_dialog_content = "¡Vamos, dame lo que tienes! Te pondré todo en el almacén, ¡ahora mismo!",
  ui_story_5012_50121501_X77_dialog_content = "Novio, llevar PlayerName Directo al pasillo!",
  ui_story_5012_50121501_77_dialog_content = "No recuerdo que el almacén estuviera en esa dirección, Lola...",
  ui_story_5012_50121501_78_dialog_content = "¡Nos vemos luego!",
  ui_story_5012_50121501_S1_dialog_content = "Ella sigue siendo tan poco refinada... No hay ningún progreso en absoluto.",
  ui_story_5012_50121501_S2_dialog_content = "Vamos, entremos.",
  ui_story_5012_50121501_79_dialog_content = "Sin embargo, PlayerName, tendrás que cerrar los ojos.",
  ui_story_5012_50121501_80_dialog_content = "¿Eh? ¿Por qué?",
  ui_story_5012_50121501_81_dialog_content = "Pronto lo verás. Ahora, por favor, toma mi mano y sígueme. Con cuidado, si quieres.",
  ui_story_5012_50121501_S3_dialog_content = "(Esto es tan misterioso... ¿Por qué no me dice simplemente si me espera una sorpresa o un susto?)",
  ui_story_5012_50121501_S4_dialog_content = "(En cuanto abra los ojos, ¿me encontraré atrapado en otro espejismo?)",
  ui_story_5012_50121501_S5_dialog_content = "Quizás?",
  ui_story_5012_50121501_S6_dialog_content = "¿Cómo sabías lo que estaba pensando?",
  ui_story_5012_50121501_S7_dialog_content = "Novio, espero que recuerdes que me invitaron a asistir a la celebración de Año Nuevo, no—",
  ui_story_5012_50121501_S8_dialog_content = "Ah, estamos aquí.",
  ui_story_5012_50121501_S9_dialog_content = "Novio...",
  ui_story_5012_50121501_82_dialog_content = "Cuando cuente hasta tres, puedes abrir los ojos.",
  ui_story_5012_50121501_83_dialog_content = "Uno...",
  ui_story_5012_50121501_S10_dialog_content = "¡Espera! ¡Despacio!",
  ui_story_5012_50121501_S11_dialog_content = "¡Ahh!",
  ui_story_5012_50121501_S12_dialog_content = "No puedo soltarme... Es demasiado peligroso.",
  ui_story_5012_50121501_84_dialog_content = "Dos...",
  ui_story_5012_50121501_S13_dialog_content = "Casi!",
  ui_story_5012_50121501_S14_dialog_content = "Apenas—",
  ui_story_5012_50121501_85_dialog_content = "Tres!",
  ui_story_5012_50121501_86_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5012_50121501_87_dialog_content = "Feliz Año Nuevo Lord PlayerName.",
  ui_story_5012_50121501_88_dialog_content = "¡Feliz Año Nuevo, a todos!",
  ui_story_5012_50121501_89_dialog_content = "El árbol que brilla... ¡Es azul!",
  ui_story_5012_50121501_90_dialog_content = "¡Mirar! Dama Nikinis ¡y los niños también están aquí para cantar villancicos!",
  ui_story_5012_50121501_91_dialog_content = "Feliz Año Nuevo, Su Majestad.",
  ui_story_5012_50121501_92_dialog_content = "¿Estamos todos listos, niños?",
  ui_story_5012_50121501_93_dialog_content = "¡Lista!",
  ui_story_5012_50121501_94_dialog_content = "¡Entonces comencemos!",
  ui_story_5012_50121501_95_dialog_content = "\"El reino del norte, nuestra graciosa madre...♪”",
  ui_story_5012_50121501_96_dialog_content = "\"Una tierra de muchas leyendas, diferente a otras...♪”",
  ui_story_5012_50121501_97_dialog_content = "\"De picos altos y nevados, y bosques de verde...♪”",
  ui_story_5012_50121501_98_dialog_content = "\"De lagos como espejos, y playas tan serenas...♪”",
  ui_story_5012_50121501_99_dialog_content = "\"Protegerla y preservarla, es todo lo que anhelo...♪”",
  ui_story_5012_50121501_100_dialog_content = "\"¡Por favor, muéstranos el camino!♪”",
  ui_story_5012_50121501_101_dialog_content = "\"Porque eres un regalo del viento y la nieve. Una estrella en la noche, eternamente resplandeciente...♪”",
  ui_story_5012_50121501_102_dialog_content = "\"Una aurora que brilla en nuestros corazones con el amor de una madre...♪”",
  ui_story_5012_50121501_103_dialog_content = "\"Y así gritamos \"¡Por el Norte!\" a la luz de arriba.♪”",
  ui_story_5012_50121501_104_dialog_content = "Aquí tienes, Carleen! ¡Feliz año nuevo!",
  ui_story_5012_50121501_105_dialog_content = "¿No es este uno de los lazos que vimos antes en el mercado?",
  ui_story_5012_50121501_106_dialog_content = "Así es. Me di cuenta de que te gustaba mucho con sólo mirar tu cara, ¡así que decidí comprarte uno!",
  ui_story_5012_50121501_107_dialog_content = "Como es un regalo, lo aceptarás... ¿Verdad?",
  ui_story_5012_50121501_108_dialog_content = "Esto es muy bonito... Gracias.",
  ui_story_5012_50121501_109_dialog_content = "Feliz Año Nuevo Lord Vice.",
  ui_story_5012_50121501_110_dialog_content = "Waaaaaah! no lo entiendo, Novio!",
  ui_story_5012_50121501_111_dialog_content = "Todos los demás niños tienen juguetes y caramelos, así que por qué...",
  ui_story_5012_50121501_112_dialog_content = "¿¡¿Por qué me dan OTRO libro sobre la historia de Northland este año?!?",
  ui_story_5012_50121501_113_dialog_content = "Te di el volumen tres de la serie el año pasado. Naturalmente, este año tendrás el cuarto volumen.",
  ui_story_5012_50121501_114_dialog_content = "¡¡Ese no es el punto!!",
  ui_story_5012_50121501_115_dialog_content = "Aprender agudiza la mente, después de todo. Harías bien en leer un poco más.",
  ui_story_5012_50121501_116_dialog_content = "¿Quién sabe? ¿Quizás el año que viene recuerdes comprar la estrella para nuestro árbol brillante?",
  ui_story_5012_50121501_117_dialog_content = "...",
  ui_story_5012_50121501_118_dialog_content = "¿Su Majestad?",
  ui_story_5012_50121501_119_dialog_content = "Hola, PlayerName. ¿Necesitas algo?",
  ui_story_5012_50121501_120_option_content = "(Ofrece el regalo)",
  ui_story_5012_50121501_121_dialog_content = "Esto es...",
  ui_story_5012_50121501_122_dialog_content = "Feliz Año Nuevo... Shaya.",
  ui_story_5012_50121501_123_dialog_content = "Gracias, PlayerName.",
  ui_story_5012_50121501_124_dialog_content = "Feliz Año Nuevo."
}
return config
